const CALENDAR_EVENT_TYPES=['MEETING','DEMO','FOLLOW_UP','DEADLINE'];
const state={user:null,view:'overview',campaign:null,phases:[],tasks:[],board:[],summary:null,analytics:null,events:[],users:[],approvals:[],workflows:[],campaigns:[],contentItems:[],notifications:[],notificationUnread:0,automations:[],filters:{status:'',priority:'',phase_id:'',assignee_id:'',search:'',due:''},calendar:{date:new Date(),mode:'month',phase_id:'',assignee:'',event_type:'',priority:'',status:'',search:'',overdue:false},calendarEvents:[]};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const api=async(url,options={})=>{const r=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let body=null;try{body=await r.json()}catch{}if(!r.ok){const e=new Error(body?.message||'Não foi possível concluir a operação.');e.status=r.status;throw e}return body};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2800)}
function showPageLoader(message='Carregando workspace...'){const el=$('#pageLoader');if(!el)return;$('#pageLoaderText').textContent=message;el.classList.add('show');el.setAttribute('aria-hidden','false');document.body.classList.add('is-loading')}
function hidePageLoader(){const el=$('#pageLoader');if(!el)return;el.classList.remove('show');el.setAttribute('aria-hidden','true');document.body.classList.remove('is-loading')}
async function withPageLoader(task,message='Carregando...',minDuration=420){const started=performance.now();showPageLoader(message);try{return await task()}finally{const elapsed=performance.now()-started;const wait=Math.max(0,minDuration-elapsed);if(wait)await new Promise(r=>setTimeout(r,wait));hidePageLoader()}}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]))}
function formatDate(v){if(!v)return '—';const [y,m,d]=String(v).slice(0,10).split('-');return `${d}/${m}/${y}`}
function badge(status){const map={BACKLOG:['Backlog',''],IN_PROGRESS:['Em execução','blue'],PENDING_APPROVAL:['Aguardando aprovação','yellow'],APPROVED:['Aprovada','green'],REJECTED:['Rejeitada','red'],DONE:['Concluída','green'],BLOCKED:['Bloqueada','red'],CRITICAL:['Crítica','red'],HIGH:['Alta','orange'],MEDIUM:['Média',''],LOW:['Baixa','']};const x=map[status]||[String(status||'').replaceAll('_',' '),''];return `<span class="badge ${x[1]}">${esc(x[0])}</span>`}
const pt={executionType:{GENERAL:'Geral',LANDING_PAGE:'Landing page',CONTENT:'Conteúdo',PAID_MEDIA:'Mídia paga',SEO:'SEO',CRM:'CRM',ANALYTICS:'Análises',AUTOMATION:'Automação',SALES:'Comercial'},role:{ADMIN:'Administrador',MANAGER:'Gestor',STAKEHOLDER:'Aprovador',USER:'Usuário'},entity:{task:'Tarefa',campaign:'Campanha',content:'Conteúdo'},workflow:{TASK:'Fluxo de tarefa',CAMPAIGN:'Fluxo de campanha',CONTENT:'Fluxo de conteúdo',TASK_STANDARD:'Fluxo de tarefa',CAMPAIGN_STANDARD:'Fluxo de campanha',CONTENT_STANDARD:'Fluxo de conteúdo'},contentStatus:{IDEA:'Ideia',BRIEF:'Briefing',PRODUCTION:'Produção',REVIEW:'Revisão',PENDING_APPROVAL:'Aguardando aprovação',APPROVED:'Aprovado',SCHEDULED:'Agendado',PUBLISHED:'Publicado',REJECTED:'Rejeitado'},contentFormat:{BLOG:'Blog',INSTAGRAM:'Instagram',FACEBOOK:'Facebook',LINKEDIN:'LinkedIn',YOUTUBE:'YouTube',REELS:'Reels',SHORTS:'Shorts',EMAIL:'E-mail',WHATSAPP:'WhatsApp'},channel:{SEO:'SEO',GOOGLE_ADS:'Google Ads',META_ADS:'Meta Ads',YOUTUBE:'YouTube',LINKEDIN:'LinkedIn',EMAIL:'E-mail',WHATSAPP:'WhatsApp',ORGANIC:'Orgânico',REFERRAL:'Indicação',PARTNERSHIP:'Parceria'},trigger:{TASK_DUE:'Tarefa com prazo hoje',TASK_OVERDUE:'Tarefa atrasada',APPROVAL_PENDING:'Aprovação pendente',CONTENT_SCHEDULED:'Conteúdo agendado',CAMPAIGN_START:'Início de campanha'}};
const ptLabel=(g,v)=>pt[g]?.[v]||String(v||'').replaceAll('_',' ');const confirmAction=m=>window.confirm(m);
function openModal(title,html){$('#modalTitle').textContent=title;$('#modalForm').innerHTML=html;$('#modal').showModal()}
function closeModal(){if($('#modal').open)$('#modal').close()}
async function load(){const [c,p,t,d,b,u,a,w,ct,co,an,no,au]=await Promise.all([api('/api/campaigns'),api('/api/phases'),api('/api/tasks'),api('/api/dashboard/summary'),api('/api/work/board'),api('/api/auth/users').catch(()=>({data:[]})),api('/api/approvals?status=PENDING').catch(()=>({data:[]})),api('/api/workflows').catch(()=>({data:[]})),api('/api/campaigns').catch(()=>({data:[]})),api('/api/content').catch(()=>({data:[]})),api('/api/analytics').catch(()=>({data:null})),api('/api/notifications').catch(()=>({data:[],meta:{unread:0}})),api('/api/automations').catch(()=>({data:[]}))]);state.campaign=c.data[0]||null;state.phases=p.data;state.tasks=t.data;state.summary=d.data;state.board=b.data;state.users=u.data||[];state.approvals=a.data||[];state.workflows=w.data||[];state.campaigns=ct.data||[];state.contentItems=co.data||[];state.analytics=an.data||null;state.notifications=no.data||[];state.notificationUnread=no.meta?.unread||0;state.automations=au.data||[];await loadCalendar();render();updateNotificationBadge()}
async function loadCalendar(){
  if(!state.campaign){state.events=[];return}
  const d=state.calendar.date; const mode=state.calendar.mode;
  let start,end;
  if(mode==='month'){start=new Date(d.getFullYear(),d.getMonth(),1);end=new Date(d.getFullYear(),d.getMonth()+1,0)}
  else if(mode==='week'){const monday=new Date(d);const offset=(monday.getDay()+6)%7;monday.setDate(monday.getDate()-offset);start=monday;end=new Date(monday);end.setDate(monday.getDate()+6)}
  else {start=new Date(d);end=new Date(d)}
  const pad=n=>String(n).padStart(2,'0');const iso=x=>`${x.getFullYear()}-${pad(x.getMonth()+1)}-${pad(x.getDate())}`;
  const q=new URLSearchParams({from:iso(start),to:iso(end)});
  if(state.calendar.phase_id)q.set('phase_id',state.calendar.phase_id);
  if(state.calendar.assignee)q.set('assignee_id',state.calendar.assignee);
  if(state.calendar.priority)q.set('priority',state.calendar.priority);
  if(state.calendar.status)q.set('status',state.calendar.status);
  if(state.calendar.search)q.set('search',state.calendar.search);
  if(state.calendar.overdue)q.set('overdue','true');
  try{const r=await api(`/api/calendar?${q}`);state.events=r.data||[];state.calendar.meta=r.meta||{}}catch{state.events=[];state.calendar.meta={}}
}
function render(){const titles={overview:'Visão geral',phases:'Roadmap 180 Dias',kanban:'Kanban',tasks:'Tarefas',calendar:'Calendário',approvals:'Aprovações',workflows:'Fluxos de trabalho',campaigns:'Campanhas',content:'Planejador de conteúdo',analytics:'Análises e indicadores',automations:'Automações'};$('#pageTitle').textContent=titles[state.view]||'Visão geral';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#approvalCount').textContent=state.approvals.length;({overview:renderOverview,phases:renderPhases,kanban:renderKanban,tasks:renderTasks,calendar:renderCalendar,approvals:renderApprovals,workflows:renderWorkflows,campaigns:renderCampaigns,content:renderContent,analytics:renderAnalytics,automations:renderAutomations}[state.view]||renderOverview)()}
function phaseCard(p,i,showMenu=false){const pct=p.task_count?Math.max(0,Math.min(100,Math.round((p.done_count/p.task_count)*100))):0;const phase=((i%6)+1);const admin=state.user?.role==='ADMIN';const menu=showMenu&&admin?`<div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu" role="menu"><button type="button" class="action-menu-item" data-edit-phase="${p.id}" role="menuitem">Editar fase</button><button type="button" class="action-menu-item danger" data-delete-phase="${p.id}" role="menuitem">Excluir fase</button></div></div>`:'';return `<article class="phase-card phase-${phase} clickable-card" data-phase-details="${p.id}" tabindex="0" role="button" aria-label="Abrir detalhes da fase ${esc(p.name)}"><div class="phase-top"><div><div class="phase-name"><span class="phase-dot"></span>${esc(p.name)}</div><div class="phase-meta">${formatDate(p.start_date)} → ${formatDate(p.end_date)} · ${esc(p.short_name||'')}</div></div><div class="phase-top-actions"><span class="badge">${pct}%</span>${menu}</div></div><div class="progress"><span class="progress-value progress-${pct}"></span></div><div class="phase-stats"><span>${p.task_count||0} tarefas</span><span>${p.done_count||0} concluídas</span><button class="btn btn-secondary btn-sm" type="button" data-open-phase="${p.id}">Ver tarefas →</button></div></article>`}

async function submitCampaignApproval(){
  if(!state.campaign)return;
  try{await api(`/api/approvals/campaigns/${state.campaign.id}/submit`,{method:'POST',body:JSON.stringify({})});toast('Campanha enviada para aprovação.');await load()}catch(e){toast(e.message)}
}
function newTask(){
  const phases=state.phases||[];
  const users=state.users||[];
  openModal('Nova tarefa',`<div class="form-grid premium-form-grid">
    <label>Nome da tarefa<span class="field-hint">Obrigatório</span><input name="title" required maxlength="220" placeholder="Ex.: Criar landing page para varejo"></label>
    <label>Fase<select name="phase_id" required>${phases.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>
    <label>Prioridade<select name="priority"><option value="LOW">Baixa</option><option value="MEDIUM" selected>Média</option><option value="HIGH">Alta</option><option value="CRITICAL">Crítica</option></select></label>
    <label>Responsável<select name="assignee_id"><option value="">Sem responsável</option>${users.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(u.role)}</option>`).join('')}</select></label>
    <label>Revisor<select name="reviewer_id"><option value="">Sem revisor</option>${users.filter(u=>['ADMIN','STAKEHOLDER'].includes(u.role)).map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(u.role)}</option>`).join('')}</select></label>
    <label>Prazo<input name="due_date" type="date"></label>
    <label>Horas estimadas<input name="estimated_hours" type="number" min="0" step="0.5" placeholder="Ex.: 4"></label>
    <label class="form-field full">Descrição<span class="field-hint">Contexto, objetivo e critérios de entrega</span><textarea name="description" rows="5" maxlength="5000" placeholder="Descreva o que precisa ser entregue..."></textarea></label>
    <div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelTask">Cancelar</button><button class="btn btn-primary" type="submit">Criar tarefa</button></div>
  </div>`);
  $('#cancelTask').onclick=closeModal;
  $('#modalForm').onsubmit=async e=>{
    e.preventDefault();
    const f=new FormData(e.currentTarget);
    try{
      showPageLoader('Criando tarefa...');
      await api('/api/tasks',{method:'POST',body:JSON.stringify({title:f.get('title'),phase_id:f.get('phase_id'),priority:f.get('priority'),assignee_id:f.get('assignee_id')||null,reviewer_id:f.get('reviewer_id')||null,due_date:f.get('due_date')||null,estimated_hours:f.get('estimated_hours')?Number(f.get('estimated_hours')):null,description:f.get('description')||null})});
      closeModal();
      await load();
      toast('Tarefa criada com sucesso.');
    }catch(err){toast(err.message)}finally{hidePageLoader()}
  };
}
function renderOverview(){const s=state.summary?.summary||{};$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Central de comando Growth</span><h2>Estratégia em execução.</h2><p>${esc(state.campaign?.description||'Configure sua campanha para começar.')}</p></div><div class="hero-actions"><button class="btn btn-secondary" data-view-action="kanban">Abrir Kanban</button>${state.campaign&&['ADMIN','MANAGER'].includes(state.user?.role)&&['DRAFT','PAUSED'].includes(state.campaign.status)?'<button class="btn btn-secondary" id="submitCampaign">Enviar campanha para aprovação</button>':''}<button class="btn btn-primary" id="heroTask">+ Tarefa</button></div></div><div class="kpis"><div class="kpi"><small>Fases</small><strong>${s.phases||0}</strong><div class="trend">roadmap</div></div><div class="kpi"><small>Tarefas</small><strong>${s.tasks||0}</strong><div class="trend">gestão de trabalho</div></div><div class="kpi"><small>Em execução</small><strong>${s.in_progress||0}</strong><div class="trend">agora</div></div><div class="kpi"><small>Aprovações</small><strong>${s.pending_approvals||0}</strong><div class="trend">pendentes</div></div><div class="kpi"><small>Atrasadas</small><strong>${s.overdue_tasks||0}</strong><div class="trend ${s.overdue_tasks?'danger-text':''}">atenção</div></div><div class="kpi"><small>Progresso</small><strong>${s.progress||0}%</strong><div class="trend">roadmap</div></div></div><div class="grid-2"><section class="panel"><div class="panel-head"><h3>Roadmap · 6 fases</h3><span class="badge orange">180 DIAS</span></div><div class="panel-body"><div class="phase-list">${state.phases.map((p,i)=>phaseCard(p,i,false)).join('')}</div></div></section><section class="panel"><div class="panel-head"><h3>Próximas tarefas</h3><button class="btn btn-secondary" data-view-action="tasks">Ver todas</button></div><div class="panel-body">${state.tasks.slice(0,7).map(taskCompact).join('')||'<div class="empty">Nenhuma tarefa.</div>'}</div></section></div>`;bindViewActions();$('#heroTask').onclick=newTask;if($('#submitCampaign'))$('#submitCampaign').onclick=submitCampaignApproval}
function taskCompact(t){return `<button class="task-compact" data-task="${t.id}"><span class="priority-dot ${t.priority.toLowerCase()}"></span><span><strong>${esc(t.title)}</strong><small>${esc(t.phase_name||'')} · ${t.due_date?formatDate(t.due_date):'Sem prazo'}</small></span>${badge(t.status)}</button>`}
async function phaseDetails(id){const phase=state.phases.find(p=>p.id===id);if(!phase)return;const tasks=state.tasks.filter(t=>t.phase_id===id);const pct=phase.task_count?Math.round((phase.done_count/phase.task_count)*100):0;openModal(`Fase · ${esc(phase.name)}`,`<div class="phase-detail"><div class="detail-hero"><div><span class="eyebrow">ROADMAP · 180 DIAS</span><h3>${esc(phase.name)}</h3><p>${esc(phase.objective||'Sem objetivo definido.')}</p></div><span class="badge orange">${pct}%</span></div><div class="detail-grid"><div class="detail-stat"><small>Período</small><strong>${formatDate(phase.start_date)} → ${formatDate(phase.end_date)}</strong></div><div class="detail-stat"><small>Tarefas</small><strong>${tasks.length}</strong></div><div class="detail-stat"><small>Concluídas</small><strong>${phase.done_count||0}</strong></div><div class="detail-stat"><small>Status</small><strong>${esc(phase.status||'PLANNED')}</strong></div></div><div class="task-detail-section"><div class="section-heading"><div><span class="eyebrow">EXECUÇÃO</span><h4>Tarefas da fase</h4></div><span class="badge">${tasks.length} itens</span></div><div class="phase-task-list">${tasks.map(t=>`<button class="phase-task-item" type="button" data-phase-task="${t.id}"><span class="priority-dot ${String(t.priority||'MEDIUM').toLowerCase()}"></span><span><strong>${esc(t.title)}</strong><small>${esc(t.due_date?`Prazo ${formatDate(t.due_date)}`:'Sem prazo')} · ${esc(t.assignee_name||'Sem responsável')}</small></span>${badge(t.status)}<span class="task-open-arrow">→</span></button>`).join('')||'<div class="empty">Nenhuma tarefa cadastrada nesta fase.</div>'}</div></div><div class="form-actions"><button type="button" class="btn btn-secondary" id="closePhaseDetails">Fechar</button>${state.user?.role==='ADMIN'?`<div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu"><button type="button" class="action-menu-item" id="editPhaseFromDetails" role="menuitem">Editar fase</button><button type="button" class="action-menu-item danger" id="deletePhaseFromDetails" role="menuitem">Excluir fase</button></div></div>`:''}</div></div>`);$('#closePhaseDetails').onclick=closeModal;if($('#editPhaseFromDetails'))$('#editPhaseFromDetails').onclick=()=>editPhase(id);if($('#deletePhaseFromDetails'))$('#deletePhaseFromDetails').onclick=()=>deletePhase(id);bindActionMenus();$$('[data-phase-task]').forEach(b=>b.onclick=()=>taskDetails(b.dataset.phaseTask))}
function renderPhases(){$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Roadmap</span><h2>180 dias, seis movimentos.</h2><p>Visão executiva do plano de Growth Marketing.</p></div>${state.user.role==='ADMIN'?'<button class="btn btn-primary" id="newPhase">+ Nova fase</button>':''}</div><section class="panel"><div class="panel-head"><h3>Fases do programa</h3><span class="badge orange">${state.phases.length} FASES</span></div><div class="panel-body"><div class="phase-list">${state.phases.map((p,i)=>phaseCard(p,i,true)).join('')}</div></div></section>`;if($('#newPhase'))$('#newPhase').onclick=newPhase;bindPhaseCards();$$('[data-edit-phase]').forEach(b=>b.onclick=e=>{e.stopPropagation();editPhase(b.dataset.editPhase)});$$('[data-delete-phase]').forEach(b=>b.onclick=e=>{e.stopPropagation();deletePhase(b.dataset.deletePhase)});bindActionMenus()}
function editPhase(id){const p=state.phases.find(x=>x.id===id);if(!p)return;openModal(`Editar fase · ${esc(p.name)}`,`<div class="form-grid premium-form-grid"><label>Nome<input name="name" required maxlength=120 value="${esc(p.name)}"></label><label>Nome curto<input name="short_name" maxlength=80 value="${esc(p.short_name||'')}"></label><label>Ordem<input name="phase_order" type="number" min="1" value="${Number(p.phase_order)||1}" required></label><label>Status<select name="status"><option value="PLANNED" ${p.status==='PLANNED'?'selected':''}>Planejada</option><option value="ACTIVE" ${p.status==='ACTIVE'?'selected':''}>Ativa</option><option value="COMPLETED" ${p.status==='COMPLETED'?'selected':''}>Concluída</option><option value="PAUSED" ${p.status==='PAUSED'?'selected':''}>Pausada</option></select></label><label>Início<input name="start_date" type="date" value="${String(p.start_date||'').slice(0,10)}"></label><label>Fim<input name="end_date" type="date" value="${String(p.end_date||'').slice(0,10)}"></label><label>Cor<input name="color" type="color" value="${esc(p.color||'#FF8A00')}"></label><label class="form-field full">Objetivo<textarea name="objective" rows="5" maxlength="3000">${esc(p.objective||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelPhaseEdit">Cancelar</button><button class="btn btn-primary">Salvar alterações</button></div></div>`);$('#cancelPhaseEdit').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/phases/${id}`,{method:'PATCH',body:JSON.stringify({name:f.get('name'),short_name:f.get('short_name'),phase_order:Number(f.get('phase_order')),status:f.get('status'),start_date:f.get('start_date')||null,end_date:f.get('end_date')||null,color:f.get('color'),objective:f.get('objective')||null})});closeModal();await load();toast('Fase atualizada.')}catch(err){toast(err.message)}}}
async function deletePhase(id){const p=state.phases.find(x=>x.id===id);if(!p||!confirmAction(`Excluir a fase “${p.name}”? As tarefas vinculadas também serão excluídas.`))return;try{await api(`/api/phases/${id}`,{method:'DELETE'});await load();toast('Fase excluída.')}catch(err){toast(err.message)}}
function newPhase(){
  const campaign=state.campaigns?.[0]||state.campaign;
  if(!campaign){toast('Nenhuma campanha disponível para a nova fase.');return}
  const nextOrder=(state.phases||[]).reduce((max,p)=>Math.max(max,Number(p.phase_order)||0),0)+1;
  openModal('Nova fase',`<div class="form-grid premium-form-grid">
    <label>Nome da fase<span class="field-hint">Obrigatório</span><input name="name" required maxlength=120 placeholder="Ex.: Fundação"></label>
    <label>Nome curto<input name="short_name" maxlength=80 placeholder="Ex.: Fundação"></label>
    <label>Ordem<input name="phase_order" type="number" min=1 step=1 value="${nextOrder}" required></label>
    <label>Status<select name="status"><option value="PLANNED" selected>Planejada</option><option value="ACTIVE">Ativa</option><option value="COMPLETED">Concluída</option><option value="PAUSED">Pausada</option></select></label>
    <label>Início<input name="start_date" type="date"></label>
    <label>Fim<input name="end_date" type="date"></label>
    <label>Cor<input name="color" type="color" value="#FF8A00"></label>
    <label class="form-field full">Objetivo<span class="field-hint">O resultado estratégico esperado nesta fase</span><textarea name="objective" rows="5" maxlength="3000" placeholder="Descreva o objetivo da fase..."></textarea></label>
    <div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelPhase">Cancelar</button><button class="btn btn-primary" type="submit">Criar fase</button></div>
  </div>`);
  $('#cancelPhase').onclick=closeModal;
  $('#modalForm').onsubmit=async e=>{
    e.preventDefault();
    const f=new FormData(e.currentTarget);
    try{
      showPageLoader('Criando fase...');
      await api('/api/phases',{method:'POST',body:JSON.stringify({campaign_id:campaign.id,phase_order:Number(f.get('phase_order')),name:f.get('name'),short_name:f.get('short_name')||f.get('name'),start_date:f.get('start_date')||null,end_date:f.get('end_date')||null,objective:f.get('objective')||null,status:f.get('status')||'PLANNED',color:f.get('color')||'#FF8A00'})});
      closeModal();
      await load();
      state.view='phases';
      render();
      toast('Fase criada com sucesso.');
    }catch(err){toast(err.message)}finally{hidePageLoader()}
  };
}
function filterBar(){return `<div class="filterbar"><div class="search-wrap"><span>⌕</span><input id="searchFilter" placeholder="Buscar tarefa..." value="${esc(state.filters.search)}"></div><select id="statusFilter" class="form-control"><option value="">Status</option>${['BACKLOG','IN_PROGRESS','PENDING_APPROVAL','APPROVED','REJECTED','DONE','BLOCKED'].map(x=>`<option ${state.filters.status===x?'selected':''} value="${x}">${x}</option>`).join('')}</select><select id="priorityFilter" class="form-control"><option value="">Prioridade</option>${['LOW','MEDIUM','HIGH','CRITICAL'].map(x=>`<option ${state.filters.priority===x?'selected':''} value="${x}">${x}</option>`).join('')}</select><select id="phaseFilter" class="form-control"><option value="">Fase</option>${state.phases.map(p=>`<option ${state.filters.phase_id===p.id?'selected':''} value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button id="clearFilters" class="btn btn-secondary">Limpar</button></div>`}
function applyFilters(){state.filters.search=$('#searchFilter')?.value.trim()||'';state.filters.status=$('#statusFilter')?.value||'';state.filters.priority=$('#priorityFilter')?.value||'';state.filters.phase_id=$('#phaseFilter')?.value||'';state.filters.due=$('#dueFilter')?.checked?'overdue':'';render()}
function filteredTasks(){return state.board.filter(t=>(!state.filters.status||t.status===state.filters.status)&&(!state.filters.priority||t.priority===state.filters.priority)&&(!state.filters.phase_id||t.phase_id===state.filters.phase_id)&&(!state.filters.search||`${t.title} ${t.description||''}`.toLowerCase().includes(state.filters.search.toLowerCase()))&&(!state.filters.due||(t.due_date&&new Date(t.due_date)<new Date()&&!['DONE','APPROVED'].includes(t.status))))}
function renderKanban(){const cols=[['BACKLOG','Backlog'],['IN_PROGRESS','Em execução'],['PENDING_APPROVAL','Aprovação'],['APPROVED','Aprovadas'],['DONE','Concluídas'],['BLOCKED','Bloqueadas']];const tasks=filteredTasks();$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Gestão de trabalho · v0.3.1</span><h2>Kanban que mostra o trabalho real.</h2><p>Arraste tarefas entre estados permitidos. Cada movimento gera histórico.</p></div><button class="btn btn-primary" id="kanbanNew">+ Nova tarefa</button></div>${filterBar()}<div class="overdue-toggle"><label><input type="checkbox" id="dueFilter" ${state.filters.due?'checked':''}> Somente atrasadas</label></div><div class="kanban-scroll"><div class="kanban-board">${cols.map(([status,label])=>`<section class="kanban-column" data-status="${status}"><header><div><strong>${label}</strong><span>${tasks.filter(t=>t.status===status).length}</span></div><small>${status==='PENDING_APPROVAL'?'Revisão':'Execução'}</small></header><div class="kanban-dropzone">${tasks.filter(t=>t.status===status).map(kanbanCard).join('')||'<div class="kanban-empty">Solte tarefas aqui</div>'}</div></section>`).join('')}</div></div>`;bindFilters();$('#kanbanNew').onclick=newTask;bindKanban();$$('[data-task]').forEach(b=>b.onclick=()=>taskDetails(b.dataset.task))}
function kanbanCard(t){const sub=t.subtask_count?`<span>☑ ${t.subtask_done_count}/${t.subtask_count}</span>`:'';const tags=(t.tags||[]).slice(0,2).map((g,i)=>`<span class="tag tag-tone-${(i%5)+1}">${esc(g.name)}</span>`).join('');return `<article class="task-card" draggable="true" data-id="${t.id}" data-task="${t.id}"><div class="task-card-top"><span class="priority-dot ${t.priority.toLowerCase()}"></span>${badge(t.priority)}<button class="card-more" data-open-task="${t.id}">•••</button></div><h4>${esc(t.title)}</h4><p>${esc((t.description||'').slice(0,110))}</p><div class="task-tags">${tags}</div><div class="task-card-foot"><span>${t.assignee_name?esc(t.assignee_name.split(' ')[0]):'Sem responsável'}</span><span>${t.due_date?formatDate(t.due_date):'Sem prazo'}</span></div>${sub?`<div class="task-progress-line"><span>${sub}</span><span>${Number(t.worked_hours||0).toFixed(1)}h</span></div>`:''}</article>`}
function bindKanban(){let dragged=null;$$('.task-card').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card;card.classList.add('dragging')});card.addEventListener('dragend',()=>{dragged=null;card.classList.remove('dragging')});card.addEventListener('click',e=>{if(e.target.closest('[data-open-task]')){e.stopPropagation();taskDetails(card.dataset.id)}})});$$('.kanban-dropzone').forEach(zone=>{zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('over')});zone.addEventListener('dragleave',()=>zone.classList.remove('over'));zone.addEventListener('drop',async e=>{e.preventDefault();zone.classList.remove('over');if(!dragged)return;const id=dragged.dataset.id,status=zone.closest('.kanban-column').dataset.status;const t=state.board.find(x=>x.id===id);try{await api(`/api/work/${id}/position`,{method:'PATCH',body:JSON.stringify({status,position:zone.children.length})});toast('Tarefa movida.');await load()}catch(err){toast(err.message)}})});$$('[data-open-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();taskDetails(b.dataset.openTask)});$$('[data-edit-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();editTask(b.dataset.editTask)});$$('[data-delete-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteTask(b.dataset.deleteTask)});bindActionMenus()}
function bindFilters(){$$('#content .filterbar select').forEach(el=>el.onchange=applyFilters);const search=$('#searchFilter');if(search)search.oninput=()=>{clearTimeout(window.__search);window.__search=setTimeout(applyFilters,220)};const clear=$('#clearFilters');if(clear)clear.onclick=()=>{state.filters={status:'',priority:'',phase_id:'',assignee_id:'',search:'',due:''};render()};const due=$('#dueFilter');if(due)due.onchange=applyFilters}
function editSubtask(taskId,subtaskId){const b=document.querySelector(`[data-edit-subtask="${subtaskId}"]`);const title=b?.closest('.execution-microtask-card')?.querySelector('b')?.textContent||'';openModal('Editar microtarefa',`<div class="form-grid premium-form-grid"><label class="form-field full">Título<input name="title" required maxlength=220 value="${esc(title)}"></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelMicroEdit">Cancelar</button><button class="btn btn-primary">Salvar alterações</button></div></div>`);$('#cancelMicroEdit').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/tasks/${taskId}/subtasks/${subtaskId}`,{method:'PATCH',body:JSON.stringify({title:f.get('title')})});closeModal();await taskDetails(taskId)}catch(err){toast(err.message)}}}
async function deleteSubtask(taskId,subtaskId){if(!confirmAction('Excluir esta microtarefa?'))return;try{await api(`/api/tasks/${taskId}/subtasks/${subtaskId}`,{method:'DELETE'});await taskDetails(taskId);toast('Microtarefa excluída.')}catch(err){toast(err.message)}}
function editTask(id){const t=state.tasks.find(x=>x.id===id)||state.board.find(x=>x.id===id);if(!t)return;openModal(`Editar tarefa · ${esc(t.title)}`,`<div class="form-grid premium-form-grid"><label>Título<input name="title" required maxlength=220 value="${esc(t.title)}"></label><label>Prioridade<select name="priority">${[['LOW','Baixa'],['MEDIUM','Média'],['HIGH','Alta'],['CRITICAL','Crítica']].map(([k,v])=>`<option value="${k}" ${t.priority===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Fase<select name="phase_id">${state.phases.map(p=>`<option value="${p.id}" ${t.phase_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Prazo<input name="due_date" type="date" value="${String(t.due_date||'').slice(0,10)}"></label><label class="form-field full">Descrição<textarea name="description" rows="5">${esc(t.description||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelTaskEdit">Cancelar</button><button class="btn btn-primary">Salvar alterações</button></div></div>`);$('#cancelTaskEdit').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify({title:f.get('title'),priority:f.get('priority'),phase_id:f.get('phase_id'),due_date:f.get('due_date')||null,description:f.get('description')||null})});closeModal();await load();toast('Tarefa atualizada.')}catch(err){toast(err.message)}}}
async function deleteTask(id){const t=state.tasks.find(x=>x.id===id)||state.board.find(x=>x.id===id);if(!t||!confirmAction(`Excluir a tarefa “${t.title}”? As microtarefas vinculadas também serão excluídas.`))return;try{await api(`/api/tasks/${id}`,{method:'DELETE'});closeModal();await load();toast('Tarefa excluída.')}catch(err){toast(err.message)}}
function renderTasks(){const tasks=filteredTasks();$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Gestão de trabalho</span><h2>Execução sem ruído.</h2><p>Detalhes operacionais, filtros e rastreabilidade.</p></div><button class="btn btn-primary" id="newTaskPage">+ Nova tarefa</button></div>${filterBar()}<section class="panel"><div class="panel-head"><h3>${tasks.length} tarefas</h3><span class="badge blue">AO VIVO</span></div><div class="table-wrap"><table class="task-table"><thead><tr><th>Tarefa</th><th>Status</th><th>Prioridade</th><th>Responsável</th><th>Prazo</th><th>Subtarefas</th><th>Horas</th><th>Ação</th></tr></thead><tbody>${tasks.map(t=>`<tr class="click-row" data-task="${t.id}"><td><strong>${esc(t.title)}</strong><div class="phase-meta">${esc(t.phase_name||'')}</div></td><td>${badge(t.status)}</td><td>${badge(t.priority)}</td><td>${esc(t.assignee_name||'—')}</td><td>${t.due_date?formatDate(t.due_date):'—'}</td><td>${t.subtask_count?`${t.subtask_done_count}/${t.subtask_count}`:'—'}</td><td>${Number(t.worked_hours||0).toFixed(1)}h</td><td><div class="action-menu-wrap table-action-menu" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu"><button type="button" class="action-menu-item" data-open-task="${t.id}" role="menuitem">Abrir</button><button type="button" class="action-menu-item" data-edit-task="${t.id}" role="menuitem">Editar</button><button type="button" class="action-menu-item danger" data-delete-task="${t.id}" role="menuitem">Excluir</button></div></div></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">Nenhuma tarefa encontrada.</div></td></tr>'}</tbody></table></div></section>`;bindFilters();$('#newTaskPage').onclick=newTask;$$('[data-task]').forEach(b=>b.onclick=()=>taskDetails(b.dataset.task));$$('[data-open-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();taskDetails(b.dataset.openTask)});$$('[data-edit-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();editTask(b.dataset.editTask)});$$('[data-delete-task]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteTask(b.dataset.deleteTask)})}

async function taskDetails(id){
  try{
    const r=await api(`/api/tasks/${id}/details`);
    const d=r.data,t=d.task;
    const progress=d.subtasks.length?Math.round((d.subtasks.filter(s=>s.is_done).length/d.subtasks.length)*100):0;
    const readiness=d.readiness||{score:0,ready:false,criteria:{total:0,required:0,completed:0,ready:false,missing:[]},evidence:{requirements:[],ready:false,missing:[]},deliverable:{ready:false,status:t.deliverable_status,has_content:Boolean(t.deliverable)}};
    const canOperate=['ADMIN','MANAGER'].includes(state.user?.role)||t.assignee_id===state.user?.id;
    const canReview=['ADMIN','STAKEHOLDER'].includes(state.user?.role);
    const canCommentTask=canOperate||state.user?.role==='STAKEHOLDER';
    const approvalActions=t.status==='PENDING_APPROVAL'&&canReview&&Boolean(t.approval_request_id);
    const acceptanceHtml=(d.acceptanceCriteria||[]).map(c=>{const computed=c.system_key==='MICROTASKS_COMPLETE'?progress===100:c.system_key==='DEAO VIVORABLE_PRESENT'?readiness.deliverable.ready:c.is_complete;return `<label class="execution-check acceptance-check ${computed?'is-done':''} ${c.system_key?'is-system':''}"><input type="checkbox" data-acceptance-toggle="${c.id}" ${computed?'checked':''} ${canOperate&&!c.system_key?'':'disabled'}><span><b>${esc(c.title)}${c.required?' <em>Obrigatório</em>':''}</b><small>${esc(c.description||'')}${c.system_key?' · Atualizado automaticamente':''}</small></span></label>`}).join('')||'<div class="empty">Nenhum critério de aceite cadastrado.</div>';
    const missingCriteriaHtml=readiness.criteria.missing.length?readiness.criteria.missing.map(c=>`<li>${esc(c.title)}</li>`).join(''):'<li>Nenhum critério pendente.</li>';
    const evidenceReqHtml=readiness.evidence.requirements.length?readiness.evidence.requirements.map(req=>`<div class="readiness-row"><span>${esc(req.label)}</span><strong>${req.actual_count}/${req.min_count} ${esc(req.evidence_type)}</strong></div>`).join(''):'<div class="empty compact">Nenhuma exigência de evidência configurada.</div>';
    const evidenceMissingHtml=readiness.evidence.missing.length?readiness.evidence.missing.map(req=>`<li>${esc(req.label)} — ${req.actual_count}/${req.min_count}</li>`).join(''):'<li>Nenhuma evidência obrigatória pendente.</li>';
    const evidenceHtml=d.evidence.map(e=>`<article class="execution-item"><div><strong>${esc(e.title)}</strong><small>${esc(e.evidence_type)} · ${esc(e.user_name||'Usuário')} · ${new Date(e.created_at).toLocaleString('pt-BR')}</small>${e.description?`<p>${esc(e.description)}</p>`:''}${e.url?`<a class="execution-link" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Abrir evidência ↗</a>`:''}</div>${canOperate?`<button type="button" class="icon-btn" data-delete-evidence="${e.id}" aria-label="Excluir evidência">×</button>`:''}</article>`).join('')||'<div class="empty">Nenhuma evidência registrada.</div>';
    const timeHtml=d.timeEntries.map(e=>`<article class="execution-item"><div><strong>${Number(e.hours).toFixed(2)}h</strong><small>${esc(e.user_name||'Usuário')} · ${new Date(e.logged_at).toLocaleString('pt-BR')}</small>${e.note?`<p>${esc(e.note)}</p>`:''}</div></article>`).join('')||'<div class="empty">Nenhum apontamento de horas.</div>';
    const commentsHtml=d.comments.map(c=>`<article class="execution-item"><div><strong>${esc(c.author_name||'Usuário')}</strong><small>${new Date(c.created_at).toLocaleString('pt-BR')}</small><p>${esc(c.body)}</p></div></article>`).join('')||'<div class="empty">Nenhum comentário ainda.</div>';
    const historyHtml=d.history.slice(0,10).map(h=>`<div class="timeline-item"><span></span><div><strong>${esc(h.to_status)}</strong><small>${esc(h.changed_by_name||'Sistema')} · ${new Date(h.created_at).toLocaleString('pt-BR')}</small>${h.note?`<p>${esc(h.note)}</p>`:''}</div></div>`).join('')||'<div class="empty">Nenhuma movimentação registrada.</div>';
    const readinessTone=readiness.ready?'green':readiness.score>=67?'yellow':'red';
    const readinessScoreClass=Math.max(0,Math.min(100,Math.round(readiness.score/10)*10));
    const approvalBlocker=!readiness.ready&&['IN_PROGRESS','REJECTED'].includes(t.status)?`<div class="approval-blocker"><strong>Não está pronto para aprovação.</strong><ul><li>Critérios: ${readiness.criteria.completed}/${readiness.criteria.required} concluídos</li><li>Evidências: ${readiness.evidence.missing.length} requisito(s) pendente(s)</li><li>Entregável: ${readiness.deliverable.ready?'pronto':'pendente'}</li></ul></div>`:'';
    const actionButtons=`<div class="execution-actions"><div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Ações da tarefa" aria-expanded="false">⋮</button><div class="action-menu action-menu-right action-menu-task" role="menu">${t.status==='BACKLOG'&&canOperate?'<button type="button" class="action-menu-item" id="startTask" role="menuitem">Iniciar execução</button>':''}${['IN_PROGRESS','REJECTED'].includes(t.status)&&canOperate?`<button type="button" class="action-menu-item" id="submitTask" ${readiness.ready?'':'disabled title="Complete o checklist, as evidências e o entregável antes de enviar."'} role="menuitem">Enviar para aprovação</button>`:''}${t.status==='APPROVED'&&canOperate?'<button type="button" class="action-menu-item" id="finishTask" role="menuitem">Concluir tarefa</button>':''}${t.status!=='BLOCKED'&&t.status!=='DONE'&&canOperate?'<button type="button" class="action-menu-item danger" id="blockTask" role="menuitem">Bloquear</button>':''}${approvalActions?'<button type="button" class="action-menu-item danger" id="rejectTaskApproval" role="menuitem">Rejeitar</button><button type="button" class="action-menu-item" id="approveTaskApproval" role="menuitem">Aprovar</button>':''}</div></div></div>`;
    openModal(`Central de execução · ${esc(t.title)}`,`<div class="task-execution-center">
      <div class="detail-hero execution-center-hero"><div><span class="eyebrow">${esc(t.phase_name||'ROADMAP')} · ${esc(t.phase_short_name||'')}</span><h3>${esc(t.title)}</h3><p>${esc(t.description||'Sem descrição.')}</p></div><div class="detail-status-stack">${badge(t.status)}${badge(t.priority)}<span class="badge blue">${esc(ptLabel('executionType',readiness.execution_type))}</span></div></div>
      <div class="execution-kpis"><div class="detail-stat"><small>Microtarefas</small><strong>${progress}%</strong></div><div class="detail-stat"><small>Prontidão para aprovação</small><strong>${readiness.score}%</strong></div><div class="detail-stat"><small>Horas</small><strong>${Number(t.worked_hours||0).toFixed(1)}h / ${t.estimated_hours!=null?Number(t.estimated_hours).toFixed(1):'—'}h</strong></div><div class="detail-stat"><small>Entregável</small><strong>${esc(t.deliverable_status||'DRAFT')}</strong></div></div>
      <div class="execution-callout"><div class="execution-icon">↗</div><div><span class="eyebrow">COMO SERÁ REALIZADA</span><p>${esc(t.execution_plan||'Plano de execução ainda não definido.')}</p></div></div>
      <section class="execution-section readiness-panel"><div class="section-heading"><div><span class="eyebrow">INTELIGÊNCIA DE APROVAÇÃO</span><h4>Prontidão para aprovação</h4></div><span class="badge ${readinessTone}">${readiness.score}% · ${readiness.ready?'PRONTO':'PENDENTE'}</span></div><div class="readiness-progress"><span class="readiness-score-${readinessScoreClass}"></span></div>${approvalBlocker}<div class="readiness-grid"><div><strong>Checklist</strong><span>${readiness.criteria.completed}/${readiness.criteria.required}</span></div><div><strong>Evidências</strong><span>${readiness.evidence.missing.length?'Pendentes':'Completas'}</span></div><div><strong>Entregável</strong><span>${readiness.deliverable.ready?'Pronto':'Pendente'}</span></div></div></section>
      <section class="execution-section"><div class="section-heading"><div><span class="eyebrow">EXECUÇÃO</span><h4>Microtarefas</h4></div><span class="badge green">${progress}%</span></div><div class="progress"><span class="progress-value progress-${progress}"></span></div><div class="execution-checklist">${(d.subtasks||[]).map(s=>`<div class="execution-microtask-card"><label class="execution-check ${s.is_done?'is-done':''}"><input type="checkbox" data-subtask-toggle="${s.id}" ${s.is_done?'checked':''} ${canOperate?'':'disabled'}><span><b>${esc(s.title)}</b><small>${s.is_done?'Concluída':'Pendente'}</small></span></label>${canOperate?`<div class="microtask-actions"><div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu"><button type="button" class="action-menu-item" data-edit-subtask="${s.id}" role="menuitem">Editar</button><button type="button" class="action-menu-item danger" data-delete-subtask="${s.id}" role="menuitem">Excluir</button></div></div></div>`:''}</div>`).join('')||'<div class="empty">Nenhuma microtarefa cadastrada.</div>'}</div>${canOperate?'<form id="newSubtaskForm" class="inline-form new-subtask-form"><input name="title" maxlength="220" placeholder="Adicionar microtarefa..." required><button class="btn btn-secondary btn-sm">+ Adicionar</button></form>':''}</section>
      <section class="execution-section acceptance-panel"><div class="section-heading"><div><span class="eyebrow">ACEITE FORMAL</span><h4>Checklist de Aceite</h4></div><span class="badge ${readiness.criteria.ready?'green':'yellow'}">${readiness.criteria.completed}/${readiness.criteria.required}</span></div><div class="execution-checklist">${acceptanceHtml}</div>${canOperate?'<form id="newAcceptanceForm" class="inline-form acceptance-add-form"><input name="title" maxlength="220" placeholder="Adicionar critério de aceite..." required><input name="description" maxlength="2000" placeholder="Como será validado?"><button class="btn btn-secondary btn-sm">+ Critério</button></form>':''}<div class="missing-list"><strong>Pendências</strong><ul>${missingCriteriaHtml}</ul></div></section>
      <section class="execution-section"><div class="section-heading"><div><span class="eyebrow">ENTREGÁVEL</span><h4>Resultado esperado e evidência final</h4></div><span class="badge ${t.deliverable_status==='APPROVED'?'green':t.deliverable_status==='SUBMITTED'?'yellow':t.deliverable_status==='REJECTED'?'red':''}">${esc(t.deliverable_status||'DRAFT')}</span></div><textarea id="taskDeliverable" class="form-control" rows="6" maxlength="10000" ${canOperate?'':'disabled'}>${esc(t.deliverable||'')}</textarea><div class="form-actions"><small class="muted">Descreva o que foi efetivamente entregue, não apenas o que estava planejado.</small>${canOperate?'<button type="button" class="btn btn-secondary" id="saveDeliverable">Salvar rascunho</button><button type="button" class="btn btn-primary" id="submitDeliverable">Salvar e enviar</button>':''}</div>${t.deliverable_submitted_at?`<div class="execution-meta">Enviado em ${new Date(t.deliverable_submitted_at).toLocaleString('pt-BR')} por ${esc(t.deliverable_submitted_by_name||'Usuário')}</div>`:''}</section>
      <section class="execution-section"><div class="section-heading"><div><span class="eyebrow">EVIDÊNCIAS</span><h4>Provas da execução</h4></div><span class="badge blue">${d.evidence.length}</span></div><div class="evidence-requirements">${evidenceReqHtml}</div><div class="execution-list">${evidenceHtml}</div>${canOperate?'<form id="evidenceForm" class="form-grid premium-form-grid"><label>Título<input name="title" maxlength="220" required placeholder="Ex.: Landing publicada"></label><label>Tipo<select name="evidence_type"><option value="LINK">Link</option><option value="NOTE">Nota</option><option value="IMAGE">Imagem</option><option value="DOCUMENT">Documento</option></select></label><label class="form-field full">URL<input name="url" maxlength="2000" placeholder="https://... (obrigatório para Link)"></label><label class="form-field full">Descrição<textarea name="description" rows="3" maxlength="4000" placeholder="O que esta evidência comprova?"></textarea></label><div class="form-actions full"><button class="btn btn-secondary" type="submit">+ Registrar evidência</button></div></form>':''}<div class="missing-list"><strong>Evidências pendentes</strong><ul>${evidenceMissingHtml}</ul></div></section>
      <section class="execution-section"><div class="section-heading"><div><span class="eyebrow">TEMPO</span><h4>Horas executadas</h4></div><span class="badge">${Number(t.worked_hours||0).toFixed(1)}h</span></div><div class="execution-list">${timeHtml}</div>${canOperate?'<form id="timeForm" class="inline-form"><input name="hours" type="number" min="0.01" max="24" step="0.25" placeholder="Horas" required><input name="note" maxlength="500" placeholder="O que foi executado?"><button class="btn btn-secondary btn-sm">+ Registrar horas</button></form>':''}</section>
      <section class="execution-section"><div class="section-heading"><div><span class="eyebrow">COLABORAÇÃO</span><h4>Comentários</h4></div><span class="badge">${d.comments.length}</span></div><div class="execution-list">${commentsHtml}</div>${canCommentTask?'<form id="commentForm" class="inline-form"><input name="body" maxlength="4000" placeholder="Registrar decisão, contexto ou observação..." required><button class="btn btn-secondary btn-sm">Comentar</button></form>':''}</section>
      ${t.status==='BLOCKED'?`<section class="execution-section blocked-panel"><div class="section-heading"><div><span class="eyebrow">BLOQUEIO</span><h4>Motivo registrado</h4></div>${badge('BLOCKED')}</div><p>${esc(t.blocked_reason||'Motivo não informado.')}</p></section>`:''}
      ${approvalActions?'<section class="execution-section approval-panel"><div class="section-heading"><div><span class="eyebrow">APROVAÇÃO</span><h4>Decisão do revisor</h4></div><span class="badge yellow">PENDENTE</span></div><textarea id="taskApprovalNote" class="form-control" rows="3" maxlength="2000" placeholder="Comentário da aprovação/rejeição..."></textarea></section>':''}
      <section class="execution-section"><div class="section-heading"><div><span class="eyebrow">RASTREABILIDADE</span><h4>Histórico</h4></div></div><div class="timeline">${historyHtml}</div></section>
      ${actionButtons}<div class="form-actions"><button type="button" class="btn btn-secondary" id="closeTaskDetails">Fechar</button>${state.user?.role==='ADMIN'||state.user?.role==='MANAGER'?`<div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu"><button type="button" class="action-menu-item" id="editTaskFromDetails" role="menuitem">Editar tarefa</button><button type="button" class="action-menu-item danger" id="deleteTaskFromDetails" role="menuitem">Excluir tarefa</button></div></div>`:''}</div>
    </div>`);
    $('#closeTaskDetails').onclick=closeModal;bindActionMenus();if($('#editTaskFromDetails'))$('#editTaskFromDetails').onclick=()=>editTask(id);if($('#deleteTaskFromDetails'))$('#deleteTaskFromDetails').onclick=()=>deleteTask(id);
    $$('[data-subtask-toggle]').forEach(el=>el.onchange=async()=>{try{await api(`/api/tasks/${id}/subtasks/${el.dataset.subtaskToggle}`,{method:'PATCH',body:JSON.stringify({is_done:el.checked})});await taskDetails(id)}catch(e){el.checked=!el.checked;toast(e.message)}});
    $$('[data-acceptance-toggle]').forEach(el=>el.onchange=async()=>{try{await api(`/api/tasks/${id}/acceptance-criteria/${el.dataset.acceptanceToggle}`,{method:'PATCH',body:JSON.stringify({is_complete:el.checked})});await taskDetails(id)}catch(e){el.checked=!el.checked;toast(e.message)}});
    $('#newSubtaskForm')?.addEventListener('submit',async e=>{e.preventDefault();const title=new FormData(e.currentTarget).get('title');try{await api(`/api/tasks/${id}/subtasks`,{method:'POST',body:JSON.stringify({title})});await taskDetails(id)}catch(err){toast(err.message)}});$$('[data-edit-subtask]').forEach(b=>b.onclick=()=>editSubtask(id,b.dataset.editSubtask));$$('[data-delete-subtask]').forEach(b=>b.onclick=()=>deleteSubtask(id,b.dataset.deleteSubtask));bindActionMenus();
    $('#newAcceptanceForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/tasks/${id}/acceptance-criteria`,{method:'POST',body:JSON.stringify({title:f.get('title'),description:f.get('description')||null,required:true})});await taskDetails(id)}catch(err){toast(err.message)}});
    $('#commentForm')?.addEventListener('submit',async e=>{e.preventDefault();const body=new FormData(e.currentTarget).get('body');try{await api(`/api/tasks/${id}/comments`,{method:'POST',body:JSON.stringify({body})});await taskDetails(id)}catch(err){toast(err.message)}});
    $('#timeForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/tasks/${id}/time`,{method:'POST',body:JSON.stringify({hours:Number(f.get('hours')),note:f.get('note')||null})});await taskDetails(id)}catch(err){toast(err.message)}});
    $('#evidenceForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/tasks/${id}/evidence`,{method:'POST',body:JSON.stringify({title:f.get('title'),evidence_type:f.get('evidence_type'),url:f.get('url')||null,description:f.get('description')||null})});await taskDetails(id)}catch(err){toast(err.message)}});
    $$('[data-delete-evidence]').forEach(b=>b.onclick=async()=>{try{await api(`/api/tasks/${id}/evidence/${b.dataset.deleteEvidence}`,{method:'DELETE'});await taskDetails(id)}catch(err){toast(err.message)}});
    const saveDeliverable=async(status)=>{const deliverable=$('#taskDeliverable').value.trim();if(!deliverable){toast('Informe o entregável realizado.');return}try{await api(`/api/tasks/${id}/deliverable`,{method:'PATCH',body:JSON.stringify({deliverable,status})});await taskDetails(id);toast(status==='SUBMITTED'?'Entregável enviado para aprovação.':'Entregável salvo.')}catch(err){toast(err.message)}};
    $('#saveDeliverable')?.addEventListener('click',()=>saveDeliverable('DRAFT'));$('#submitDeliverable')?.addEventListener('click',()=>saveDeliverable('SUBMITTED'));
    $('#startTask')?.addEventListener('click',async()=>{try{await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify({status:'IN_PROGRESS'})});await load();await taskDetails(id);toast('Execução iniciada.')}catch(err){toast(err.message)}});
    $('#submitTask')?.addEventListener('click',async()=>{try{await api(`/api/tasks/${id}/submit`,{method:'POST',body:JSON.stringify({})});await load();await taskDetails(id);toast('Tarefa enviada para aprovação.')}catch(err){toast(err.message)}});
    $('#finishTask')?.addEventListener('click',async()=>{try{await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify({status:'DONE'})});await load();await taskDetails(id);toast('Tarefa concluída.')}catch(err){toast(err.message)}});
    $('#blockTask')?.addEventListener('click',async()=>{const reason=window.prompt('Informe o motivo do bloqueio:');if(!reason)return;try{await api(`/api/tasks/${id}/block`,{method:'POST',body:JSON.stringify({reason})});await load();await taskDetails(id);toast('Tarefa bloqueada.')}catch(err){toast(err.message)}});
    $('#approveTaskApproval')?.addEventListener('click',async()=>{try{if(!t.approval_request_id)throw new Error('Solicitação de aprovação não encontrada.');await api(`/api/approvals/${t.approval_request_id}/decision`,{method:'POST',body:JSON.stringify({decision:'APPROVED',comment:$('#taskApprovalNote')?.value.trim()||'Aprovada.'})});await load();await taskDetails(id);toast('Tarefa aprovada.')}catch(err){toast(err.message)}});
    $('#rejectTaskApproval')?.addEventListener('click',async()=>{const note=$('#taskApprovalNote')?.value.trim()||'';if(!note){toast('Informe o motivo da rejeição.');return}try{if(!t.approval_request_id)throw new Error('Solicitação de aprovação não encontrada.');await api(`/api/approvals/${t.approval_request_id}/decision`,{method:'POST',body:JSON.stringify({decision:'REJECTED',comment:note})});await load();await taskDetails(id);toast('Tarefa rejeitada.')}catch(err){toast(err.message)}});
  }catch(e){toast(`Não foi possível abrir a tarefa: ${e.message}`)}
}
function renderApprovals(){const items=state.approvals||[];$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Governança</span><h2>Aprovações claras e rastreáveis.</h2><p>Veja exatamente o que precisa ser aprovado, quais critérios foram atendidos e quais evidências sustentam a decisão.</p></div></div><section class="panel"><div class="panel-head"><h3>${items.length} solicitações pendentes</h3><span class="badge yellow">GOVERNANÇA</span></div><div class="panel-body approval-list">${items.map(a=>{const tipo=ptLabel('entity',a.entity);const titulo=a.task_title||a.content_title||a.campaign_name||'Entidade';return `<button type="button" class="approval-card" data-approval="${a.id}"><div><small class="approval-card-kicker">${esc(tipo)} · ${esc(ptLabel('workflow',a.workflow))}</small><strong>${esc(titulo)}</strong><p><b>O que você precisa aprovar:</b> ${esc(tipo==='Tarefa'?'a execução, os critérios de aceite, as evidências e o entregável.':tipo==='Conteúdo'?'o conteúdo e sua liberação para publicação.':'o direcionamento e a ativação da campanha.')}</p><div class="phase-meta">Solicitado por ${esc(a.requested_by_name||a.assignee_name||'Usuário')} · ${esc(a.phase_name||'')}</div></div><span>Revisar →</span></button>`}).join('')||'<div class="empty">Nenhuma aprovação pendente.</div>'}</div></section>`;$$('[data-approval]').forEach(b=>b.onclick=()=>approvalDetails(b.dataset.approval))}


async function approvalDetails(id){try{const r=await api(`/api/approvals/${id}`);const d=r.data;const step=d.steps.find(x=>x.status==='PENDING');const ctx=d.context||{};const type=ptLabel('entity',d.request.entity);let body='';if(d.request.entity==='task'&&ctx.task){body=`<div class="approval-purpose"><strong>O que está sendo aprovado</strong><p>Você está aprovando a execução da tarefa, o cumprimento dos critérios de aceite, as evidências apresentadas e o entregável registrado.</p></div><div class="approval-context-grid"><div><small>Fase</small><strong>${esc(ctx.task.phase_name||'—')}</strong></div><div><small>Campanha</small><strong>${esc(ctx.task.campaign_name||'—')}</strong></div><div><small>Prontidão</small><strong>${ctx.readiness?.score||0}%</strong></div><div><small>Entregável</small><strong>${ctx.readiness?.deliverable?.ready?'Pronto':'Pendente'}</strong></div></div><section class="approval-detail-section"><h4>Critérios de aceite</h4>${(ctx.criteria||[]).map(c=>`<div class="approval-check-row"><span>${c.is_complete?'✓':'○'}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.description||'')}${c.required?' · Obrigatório':''}</small></div></div>`).join('')||'<div class="empty">Nenhum critério.</div>'}</section><section class="approval-detail-section"><h4>Evidências apresentadas</h4>${(ctx.evidence||[]).map(e=>`<article class="approval-evidence-row"><div><strong>${esc(e.title)}</strong><small>${esc(e.evidence_type)} · ${new Date(e.created_at).toLocaleString('pt-BR')}</small></div>${e.url?`<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Abrir evidência</a>`:''}</article>`).join('')||'<div class="empty">Nenhuma evidência.</div>'}</section>`}else if(d.request.entity==='content'&&ctx.content){body=`<div class="approval-purpose"><strong>O que está sendo aprovado</strong><p>Você está aprovando este conteúdo para avançar no fluxo de publicação.</p></div><div class="approval-context-grid"><div><small>Formato</small><strong>${esc(ptLabel('contentFormat',ctx.content.format))}</strong></div><div><small>Canal</small><strong>${esc(ptLabel('channel',ctx.content.channel))}</strong></div><div><small>Campanha</small><strong>${esc(ctx.content.campaign_name||'—')}</strong></div><div><small>Fase</small><strong>${esc(ctx.content.phase_name||'—')}</strong></div></div><section class="approval-detail-section"><h4>Conteúdo para revisão</h4><h4>${esc(ctx.content.title)}</h4><p>${esc(ctx.content.copy||'Sem copy cadastrada.')}</p>${ctx.content.cta?`<p><strong>CTA:</strong> ${esc(ctx.content.cta)}</p>`:''}</section>`}else if(d.request.entity==='campaign'&&ctx.campaign){body=`<div class="approval-purpose"><strong>O que está sendo aprovado</strong><p>Você está aprovando o direcionamento estratégico e a ativação desta campanha.</p></div><div class="approval-context-grid"><div><small>Segmento</small><strong>${esc(ctx.campaign.target_segment||'—')}</strong></div><div><small>Período</small><strong>${formatDate(ctx.campaign.start_date)} → ${formatDate(ctx.campaign.end_date)}</strong></div><div><small>Orçamento</small><strong>R$ ${((Number(ctx.campaign.budget_cents)||0)/100).toLocaleString('pt-BR',{minimumFractionDigits:2})}</strong></div></div><section class="approval-detail-section"><h4>Objetivo</h4><p>${esc(ctx.campaign.objective||ctx.campaign.description||'Sem objetivo cadastrado.')}</p></section>`}openModal(`Revisão para aprovação · ${esc(type)}`,`<div class="approval-detail"><div class="detail-hero"><div><span class="section-label">${esc(type)}</span><h3>${esc(d.request.task_title||d.request.content_title||d.request.campaign_name||'Solicitação')}</h3><p>Solicitado por ${esc(d.request.requested_by_name||'Usuário')} em ${new Date(d.request.requested_at).toLocaleString('pt-BR')}.</p></div>${badge(d.request.status)}</div>${body}<section class="approval-detail-section"><h4>Etapas da aprovação</h4>${d.steps.map(x=>`<div class="approval-step"><strong>Etapa ${x.step_order}</strong><span>${esc(x.approver_user_name||ptLabel('role',x.approver_role)||'Aprovador')}</span>${badge(x.status)}${x.last_comment?`<p>${esc(x.last_comment)}</p>`:''}</div>`).join('')}</section>${step?`<section class="approval-decision"><h4>Sua decisão</h4><p>Valide o conteúdo acima antes de decidir.</p><label>Comentário da decisão<textarea id="approvalComment" class="form-control" rows=4 placeholder="Explique o motivo da aprovação ou rejeição..."></textarea></label><div class="form-actions"><button type="button" class="btn btn-danger" id="rejectApproval">Rejeitar</button><button type="button" class="btn btn-primary" id="approveApproval">Aprovar</button></div></section>`:'<div class="empty compact">Esta solicitação não está aguardando sua decisão.</div>'}</div>`);if(step){$('#approveApproval').onclick=()=>decideApproval(id,'APPROVED');$('#rejectApproval').onclick=()=>decideApproval(id,'REJECTED')}}catch(e){toast(e.message)}}


async function decideApproval(id,decision){try{const comment=$('#approvalComment')?.value.trim()||'';await api(`/api/approvals/${id}/decision`,{method:'POST',body:JSON.stringify({decision,comment})});closeModal();toast(decision==='APPROVED'?'Etapa aprovada.':'Aprovação rejeitada.');await load();state.view='approvals';render()}catch(e){toast(e.message)}}
async function workflowStatus(id,status){try{await api(`/api/workflows/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});toast(status==='ACTIVE'?'Workflow ativado.':'Status atualizado.');await load();state.view='workflows';render()}catch(e){toast(e.message)}}
function renderWorkflows(){
  const canManage=['ADMIN','MANAGER'].includes(state.user?.role);
  $('#content').innerHTML=`<div class="hero"><div><span class="section-label">Governança · v0.5.0</span><h2>Fluxos de trabalho de aprovação.</h2><p>Fluxos reutilizáveis, etapas ordenadas e decisões rastreáveis. Cada solicitação recebe uma fotografia imutável das etapas.</p></div></div>
  <section class="panel"><div class="panel-head"><h3>${state.workflows.length} workflows</h3><span class="badge yellow">GOVERNANÇA</span></div>
  <div class="panel-body workflow-list">${state.workflows.map(w=>`<article class="workflow-card"><div><strong>${esc(w.name)}</strong><div class="phase-meta">${esc(w.entity_type)} · ${esc(w.status)} · ${esc(w.description||'')}</div><div class="approval-steps">${(w.steps||[]).map(s=>`<span class="step-chip">${s.step_order}. ${esc(s.name)} · ${esc(s.approver_user_id?'Usuário':s.approver_role||'—')}</span>`).join('')}</div></div>${canManage?`<div class="workflow-actions"><div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu">${w.status!=='ACTIVE'?`<button type="button" class="action-menu-item" data-workflow-active="${w.id}" role="menuitem">Ativar fluxo</button>`:''}${w.status!=='ARCHIVED'?`<button type="button" class="action-menu-item" data-workflow-archive="${w.id}" role="menuitem">Arquivar fluxo</button>`:''}</div></div></div>`:''}</article>`).join('')||'<div class="empty">Nenhum workflow configurado.</div>'}</div></section>`;
  $$('[data-workflow-active]').forEach(b=>b.onclick=()=>workflowStatus(b.dataset.workflowActive,'ACTIVE'));
  $$('[data-workflow-archive]').forEach(b=>b.onclick=()=>workflowStatus(b.dataset.workflowArchive,'ARCHIVED'));bindActionMenus();
}

function calendarEvent(e){const flags=`${e.is_overdue?' overdue':''}${e.is_critical?' critical':''}${e.event_type?' calendar-event-'+String(e.event_type).toLowerCase():''}`;const kind=e.event_type?'event':'task';const meta=e.event_type?`${e.event_type.replace('_',' ')} · ${e.status||'SCHEDULED'}`:`${e.priority} · ${e.status}`;return `<button class="event${flags}" draggable="true" data-calendar-kind="${kind}" data-calendar-id="${e.id}" title="${esc(e.title)} · ${esc(e.phase_name||'')}" type="button"><span class="event-type-dot"></span><span class="event-copy"><strong>${esc(e.title)}</strong><small>${esc(meta)}</small></span></button>`}

function calendarControls(){return `<div class="calendar-filters"><div class="search-wrap"><span>⌕</span><input id="calSearch" value="${esc(state.calendar.search||'')}" placeholder="Buscar tarefa, reunião ou evento" aria-label="Buscar no calendário"></div><select id="calPhase" class="form-control"><option value="">Todas as fases</option>${state.phases.map(p=>`<option value="${p.id}" ${state.calendar.phase_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="calAssignee" class="form-control"><option value="">Todos responsáveis</option>${state.users.map(u=>`<option value="${u.id}" ${state.calendar.assignee===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select><select id="calType" class="form-control"><option value="">Todos os tipos</option>${['MEETING','DEMO','FOLLOW_UP','CAMPAIGN','DEADLINE','OTHER'].map(x=>`<option value="${x}" ${state.calendar.event_type===x?'selected':''}>${x.replace('_',' ')}</option>`).join('')}</select><select id="calPriority" class="form-control"><option value="">Todas prioridades</option><option value="CRITICAL" ${state.calendar.priority==='CRITICAL'?'selected':''}>Críticas</option><option value="HIGH" ${state.calendar.priority==='HIGH'?'selected':''}>Altas</option><option value="MEDIUM" ${state.calendar.priority==='MEDIUM'?'selected':''}>Médias</option><option value="LOW" ${state.calendar.priority==='LOW'?'selected':''}>Baixas</option></select><label class="calendar-check"><input id="calOverdue" type="checkbox" ${state.calendar.overdue?'checked':''}> Atrasadas</label></div>`}

function calendarRange(){const d=state.calendar.date;let start,end;if(state.calendar.mode==='month'){start=new Date(d.getFullYear(),d.getMonth(),1);end=new Date(d.getFullYear(),d.getMonth()+1,0)}else if(state.calendar.mode==='week'){const monday=new Date(d);const offset=(monday.getDay()+6)%7;monday.setDate(monday.getDate()-offset);start=monday;end=new Date(monday);end.setDate(monday.getDate()+6)}else{start=new Date(d);end=new Date(d)}return {start,end}}

function calendarTitle(){const d=state.calendar.date;if(state.calendar.mode==='month')return d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});if(state.calendar.mode==='week'){const {start,end}=calendarRange();return `${start.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})} — ${end.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}`}if(state.calendar.mode==='day')return d.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'});return 'Agenda de execução'}

function allCalendarItems(){return [...state.events,...(state.calendarEvents||[])].map(e=>e.event_type?e:{...e,calendar_kind:'task'});}

function itemsForDate(iso){return allCalendarItems().filter(e=>String(e.due_date||e.start_at).slice(0,10)===iso)}

function newCalendarEvent(date){const d=date||state.calendar.date;const pad=n=>String(n).padStart(2,'0');const dateStr=`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;openModal('Novo evento no calendário',`<div class="form-grid"><label>Título<input name="title" required maxlength="220" placeholder="Ex.: Reunião de alinhamento"></label><label>Tipo<select name="event_type"><option>MEETING</option><option>DEMO</option><option>FOLLOW_UP</option><option>CAMPAIGN</option><option>DEADLINE</option><option>OTHER</option></select></label><label>Início<input name="start_at" type="datetime-local" required value="${dateStr}T09:00"></label><label>Término<input name="end_at" type="datetime-local" value="${dateStr}T10:00"></label><label class="form-field full">Local<input name="location" maxlength="300" placeholder="Sala, endereço ou link"></label><label class="form-field full">Descrição<textarea name="description" rows="4" maxlength="4000"></textarea></label><label class="calendar-check"><input name="all_day" type="checkbox"> Dia inteiro</label><div class="form-actions"><button type="button" class="btn btn-secondary" id="cancelEvent">Cancelar</button><button class="btn btn-primary" type="submit">Criar evento</button></div></div>`);$('#cancelEvent').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/calendar-events',{method:'POST',body:JSON.stringify({title:f.get('title'),event_type:f.get('event_type'),start_at:new Date(f.get('start_at')).toISOString(),end_at:f.get('end_at')?new Date(f.get('end_at')).toISOString():null,location:f.get('location')||null,description:f.get('description')||null,all_day:f.get('all_day')==='on'})});closeModal();toast('Evento criado.');await loadCalendar();render()}catch(err){toast(err.message)}}}

function openContentModal(){openModal('Novo conteúdo',`<div class="form-grid premium-form-grid"><label>Título<input name="title" required maxlength="220"></label><label>Formato<select name="format">${['BLOG','INSTAGRAM','FACEBOOK','LINKEDIN','YOUTUBE','REELS','SHORTS','EMAIL','WHATSAPP'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Canal<select name="channel">${['SEO','GOOGLE_ADS','META_ADS','YOUTUBE','LINKEDIN','EMAIL','WHATSAPP','ORGANIC','REFERRAL','PARTNERSHIP'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Campanha<select name="campaign_id"><option value="">Sem campanha</option>${state.campaigns.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Fase<select name="phase_id"><option value="">Sem fase</option>${state.phases.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Agendamento<input name="scheduled_at" type="datetime-local"></label><label class="calendar-check"><input name="create_calendar" type="checkbox" checked> Criar item no calendário</label><label class="form-field full">Copy<textarea name="copy" rows="6" maxlength="10000"></textarea></label><label class="form-field full">CTA<input name="cta" maxlength="300" placeholder="Ex.: Quero conhecer minha solução G3Soft"></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelContent">Cancelar</button><button class="btn btn-primary">Criar conteúdo</button></div></div>`);$('#cancelContent').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const scheduled=f.get('scheduled_at')?new Date(f.get('scheduled_at')).toISOString():null;const created=await api('/api/content',{method:'POST',body:JSON.stringify({title:f.get('title'),format:f.get('format'),channel:f.get('channel'),campaign_id:f.get('campaign_id')||null,phase_id:f.get('phase_id')||null,scheduled_at:scheduled,copy:f.get('copy'),cta:f.get('cta')})});if(scheduled&&f.get('create_calendar')){const ev=await api('/api/calendar-events',{method:'POST',body:JSON.stringify({title:f.get('title'),event_type:'CAMPAIGN',start_at:scheduled,end_at:new Date(new Date(scheduled).getTime()+3600000).toISOString(),campaign_id:f.get('campaign_id')||null,phase_id:f.get('phase_id')||null,content_id:created.data.id,owner_id:state.user.id})});await api(`/api/content/${created.data.id}`,{method:'PATCH',body:JSON.stringify({calendar_event_id:ev.data.id})})}closeModal();toast('Conteúdo criado e conectado ao calendário.');await load()}catch(e){toast(e.message)}}}

function editAutomation(id){const x=state.automations.find(a=>a.id===id);if(!x)return;openModal(`Editar automação · ${esc(x.name)}`,`<div class="form-grid premium-form-grid"><label>Nome<input name="name" required maxlength=180 value="${esc(x.name)}"></label><label>Gatilho<select name="trigger_type" disabled><option>${esc(ptLabel('trigger',x.trigger_type))}</option></select></label><label class="form-field full">Descrição<textarea name="description" rows=4>${esc(x.description||'')}</textarea></label><label>Status<select name="is_active"><option value="true" ${x.is_active?'selected':''}>Ativa</option><option value="false" ${!x.is_active?'selected':''}>Inativa</option></select></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelAutomationEdit">Cancelar</button><button class="btn btn-primary">Salvar alterações</button></div></div>`);$('#cancelAutomationEdit').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/automations/${id}`,{method:'PATCH',body:JSON.stringify({name:f.get('name'),description:f.get('description'),is_active:f.get('is_active')==='true'})});closeModal();await load();toast('Automação atualizada.')}catch(err){toast(err.message)}}}
async function deleteAutomation(id){const x=state.automations.find(a=>a.id===id);if(!x||!confirmAction(`Excluir a automação “${x.name}”?`))return;try{await api(`/api/automations/${id}`,{method:'DELETE'});await load();toast('Automação excluída.')}catch(err){toast(err.message)}}
function newAutomation(){openModal('Nova automação',`<div class="form-grid premium-form-grid"><label>Nome<input name="name" required maxlength=180 placeholder="Ex.: Avisar tarefas atrasadas"></label><label>Gatilho<select name="trigger_type"><option value="TASK_DUE">Tarefa com prazo hoje</option><option value="TASK_OVERDUE">Tarefa atrasada</option><option value="APPROVAL_PENDING">Aprovação pendente</option><option value="CONTENT_SCHEDULED">Conteúdo agendado</option><option value="CAMPAIGN_START">Início de campanha</option></select></label><label class="form-field full">Descrição<textarea name="description" rows=4 placeholder="Explique quando e por que esta regra deve atuar..."></textarea></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelAutomation">Cancelar</button><button class="btn btn-primary">Criar automação</button></div></div>`);$('#cancelAutomation').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/automations',{method:'POST',body:JSON.stringify({name:f.get('name'),trigger_type:f.get('trigger_type'),description:f.get('description')||null})});closeModal();await load();toast('Automação criada.')}catch(err){toast(err.message)}}}

function renderCampaigns(){const channels=['SEO','GOOGLE_ADS','META_ADS','YOUTUBE','LINKEDIN','EMAIL','WHATSAPP','ORGANIC','REFERRAL','PARTNERSHIP'];$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Motor de crescimento</span><h2>Campanhas que conectam estratégia e execução.</h2><p>Campanha → fases → tarefas → conteúdo → calendário → aprovação.</p></div><button class="btn btn-primary" id="newCampaignGrowth">+ Nova campanha</button></div><div class="grid-2">${state.campaigns.map(c=>`<section class="panel"><div class="panel-head"><div><h3>${esc(c.name)}</h3><span class="phase-meta">${esc(c.target_segment||'Growth B2B')} · ${formatDate(c.start_date)} → ${formatDate(c.end_date)}</span></div>${badge(c.status)}</div><div class="panel-body"><p class="muted">${esc(c.objective||c.description||'Sem objetivo definido.')}</p><div class="campaign-metrics"><span>Orçamento <b>R$ ${((Number(c.budget_cents)||0)/100).toLocaleString('pt-BR',{minimumFractionDigits:2})}</b></span><span>Landing page <b>${c.landing_page_url?'definida':'pendente'}</b></span></div><div class="tag-row">${channels.slice(0,4).map(x=>`<span class="tag">${esc(ptLabel('channel',x))}</span>`).join('')}</div><div class="form-actions campaign-card-actions"><button class="btn btn-secondary" data-view-action="phases">Abrir roadmap</button><button class="btn btn-secondary" data-view-action="content">Ver conteúdo</button><div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu"><button type="button" class="action-menu-item" data-edit-campaign="${c.id}" role="menuitem">Editar campanha</button><button type="button" class="action-menu-item danger" data-delete-campaign="${c.id}" role="menuitem">Excluir campanha</button></div></div></div></div></section>`).join('')||'<div class="empty">Nenhuma campanha encontrada.</div>'}</div>`;bindViewActions();$('#newCampaignGrowth').onclick=()=>openCampaignModal();$$('[data-edit-campaign]').forEach(b=>b.onclick=()=>editCampaign(b.dataset.editCampaign));$$('[data-delete-campaign]').forEach(b=>b.onclick=()=>deleteCampaign(b.dataset.deleteCampaign));bindActionMenus()}


function openCampaignModal(){openModal('Nova campanha Growth',`<div class="form-grid premium-form-grid"><label>Nome<input name="name" required maxlength="180"></label><label>Segmento<input name="target_segment" maxlength="160" placeholder="Ex.: varejo B2B"></label><label>Início<input name="start_date" type="date"></label><label>Fim<input name="end_date" type="date"></label><label class="form-field full">Objetivo<textarea name="objective" rows="3" maxlength="3000"></textarea></label><label>Orçamento (R$)<input name="budget" type="number" min="0" step="0.01"></label><label>Landing page<input name="landing_page_url" maxlength="500"></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelCampaign">Cancelar</button><button class="btn btn-primary">Criar campanha</button></div></div>`);$('#cancelCampaign').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/campaigns',{method:'POST',body:JSON.stringify({name:f.get('name'),target_segment:f.get('target_segment'),start_date:f.get('start_date')||null,end_date:f.get('end_date')||null,objective:f.get('objective'),budget_cents:Math.round(Number(f.get('budget')||0)*100),landing_page_url:f.get('landing_page_url')||null})});closeModal();toast('Campanha criada.');await load()}catch(e){toast(e.message)}}}
function editContent(id){const x=state.contentItems.find(c=>c.id===id);if(!x)return;openModal(`Editar conteúdo · ${esc(x.title)}`,`<div class="form-grid premium-form-grid"><label>Título<input name="title" required maxlength=220 value="${esc(x.title)}"></label><label>Formato<select name="format">${Object.entries(pt.contentFormat).map(([k,v])=>`<option value="${k}" ${x.format===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Canal<select name="channel">${Object.entries(pt.channel).map(([k,v])=>`<option value="${k}" ${x.channel===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Campanha<select name="campaign_id"><option value="">Sem campanha</option>${state.campaigns.map(c=>`<option value="${c.id}" ${x.campaign_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Fase<select name="phase_id"><option value="">Sem fase</option>${state.phases.map(q=>`<option value="${q.id}" ${x.phase_id===q.id?'selected':''}>${esc(q.name)}</option>`).join('')}</select></label><label>Agendamento<input name="scheduled_at" type="datetime-local" value="${x.scheduled_at?new Date(x.scheduled_at).toISOString().slice(0,16):''}"></label><label class="form-field full">Copy<textarea name="copy" rows=6 maxlength=10000>${esc(x.copy||'')}</textarea></label><label class="form-field full">CTA<input name="cta" maxlength=300 value="${esc(x.cta||'')}"></label><div class="form-actions full"><button type="button" class="btn btn-secondary" id="cancelContentEdit">Cancelar</button><button class="btn btn-primary">Salvar alterações</button></div></div>`);$('#cancelContentEdit').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/content/${id}`,{method:'PATCH',body:JSON.stringify({title:f.get('title'),format:f.get('format'),channel:f.get('channel'),campaign_id:f.get('campaign_id')||null,phase_id:f.get('phase_id')||null,scheduled_at:f.get('scheduled_at')?new Date(f.get('scheduled_at')).toISOString():null,copy:f.get('copy'),cta:f.get('cta')})});closeModal();await load();toast('Conteúdo atualizado.')}catch(err){toast(err.message)}}}
async function deleteContent(id){const x=state.contentItems.find(c=>c.id===id);if(!x||!confirmAction(`Excluir o conteúdo “${x.title}”?`))return;try{await api(`/api/content/${id}`,{method:'DELETE'});await load();toast('Conteúdo excluído.')}catch(err){toast(err.message)}}
function renderContent(){const items=state.contentItems;const groups=['IDEA','BRIEF','PRODUCTION','REVIEW','PENDING_APPROVAL','APPROVED','SCHEDULED','PUBLISHED','REJECTED'];$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Planejador de conteúdo</span><h2>Conteúdo com fluxo de Growth.</h2><p>Planeje, produza, revise, aprove e publique conteúdos ligados a campanhas, fases e calendário.</p></div><button class="btn btn-primary" id="newContent">+ Novo conteúdo</button></div><div class="content-board">${groups.map(g=>`<section class="content-column" data-content-status="${g}"><header><strong>${esc(ptLabel('contentStatus',g))}</strong><span>${items.filter(x=>x.status===g).length}</span></header><div class="content-dropzone" data-content-drop-status="${g}">${items.filter(x=>x.status===g).map(contentCard).join('')||'<div class="column-empty">Solte o conteúdo aqui</div>'}</div></section>`).join('')}</div>`;$('#newContent').onclick=()=>openContentModal();$$('[data-content-submit]').forEach(b=>b.onclick=async e=>{e.preventDefault();e.stopPropagation();const id=b.dataset.contentSubmit;const old=b.textContent;b.disabled=true;b.textContent='Enviando...';try{await api(`/api/approvals/content/${id}/submit`,{method:'POST',body:JSON.stringify({})});toast('Conteúdo enviado para aprovação.');await load()}catch(err){toast(err.message);b.disabled=false;b.textContent=old}});$$('[data-edit-content]').forEach(b=>b.onclick=e=>{e.stopPropagation();editContent(b.dataset.editContent)});$$('[data-delete-content]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteContent(b.dataset.deleteContent)});bindContentPlanner();bindActionMenus()}


function contentCard(x){return `<article class="content-card" draggable="true" data-content-card="${x.id}"><div class="content-card-top"><span class="tag">${esc(ptLabel('contentFormat',x.format))}</span>${badge(x.status)}</div><h4>${esc(x.title)}</h4><p>${esc(x.campaign_name||'Sem campanha')} · ${esc(x.phase_name||'Sem fase')}</p><small>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString('pt-BR'):'Sem agendamento'}</small><div class="form-actions content-card-actions"><button class="btn btn-primary btn-sm" data-content-submit="${x.id}" ${!['IDEA','BRIEF','PRODUCTION','REVIEW','REJECTED'].includes(x.status)?'disabled':''}>Enviar para aprovação</button><div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu"><button type="button" class="action-menu-item" data-edit-content="${x.id}" role="menuitem">Editar conteúdo</button><button type="button" class="action-menu-item danger" data-delete-content="${x.id}" role="menuitem">Excluir conteúdo</button></div></div></div></article>`}


function bindContentPlanner(){let dragged=null;$$('[data-content-card]').forEach(card=>{card.addEventListener('dragstart',e=>{dragged=card;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',card.dataset.contentCard)});card.addEventListener('dragend',()=>{dragged=null;card.classList.remove('dragging')})});$$('[data-content-drop-status]').forEach(zone=>{zone.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';zone.classList.add('drop-target')});zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))zone.classList.remove('drop-target')});zone.addEventListener('drop',async e=>{e.preventDefault();zone.classList.remove('drop-target');const id=e.dataTransfer.getData('text/plain')||dragged?.dataset.contentCard;const status=zone.dataset.contentDropStatus;if(!id||!status)return;const current=state.contentItems.find(x=>x.id===id);if(!current||current.status===status)return;try{await api(`/api/content/${id}`,{method:'PATCH',body:JSON.stringify({status})});toast(`Conteúdo movido para ${status.replace('_',' ')}.`);await load()}catch(err){toast(err.message)}})})}

function renderAutomations(){const items=state.automations||[];$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Automações</span><h2>Automações operacionais.</h2><p>Regras para tarefas, aprovações, conteúdos e campanhas.</p></div><button class="btn btn-primary" id="newAutomationBtn">+ Nova automação</button></div><section class="panel"><div class="panel-head"><h3>${items.length} regras</h3><span class="badge blue">AUTOMAÇÕES</span></div><div class="panel-body"><div class="automation-grid">${items.map(x=>`<article class="automation-card"><header><div><h3>${esc(x.name)}</h3><p>${esc(ptLabel('trigger',x.trigger_type))} · ${x.run_count||0} execuções</p></div><span class="badge ${x.is_active?'green':'red'}">${x.is_active?'ATIVA':'INATIVA'}</span></header>${x.description?`<p>${esc(x.description)}</p>`:''}<div class="automation-actions"><div class="action-menu-wrap" data-action-menu><button type="button" class="icon-btn action-menu-trigger" data-action-menu-trigger aria-label="Mais opções" aria-expanded="false">⋮</button><div class="action-menu action-menu-right" role="menu"><button type="button" class="action-menu-item" data-edit-automation="${x.id}" role="menuitem">Editar automação</button><button type="button" class="action-menu-item danger" data-delete-automation="${x.id}" role="menuitem">Excluir automação</button></div></div></div></article>`).join('')||'<div class="empty">Nenhuma automação configurada.</div>'}</div></div></section>`;$('#newAutomationBtn').onclick=newAutomation;$$('[data-edit-automation]').forEach(b=>b.onclick=()=>editAutomation(b.dataset.editAutomation));$$('[data-delete-automation]').forEach(b=>b.onclick=()=>deleteAutomation(b.dataset.deleteAutomation));bindActionMenus()}

function bindActionMenus(){const menus=$$('[data-action-menu]');menus.forEach(w=>{const trigger=w.querySelector('[data-action-menu-trigger]');if(!trigger||trigger.dataset.bound==='1')return;trigger.dataset.bound='1';trigger.onclick=e=>{e.preventDefault();e.stopPropagation();menus.forEach(other=>{if(other!==w){other.classList.remove('is-open');other.querySelector('[data-action-menu-trigger]')?.setAttribute('aria-expanded','false')}});const open=w.classList.toggle('is-open');trigger.setAttribute('aria-expanded',open?'true':'false');const card=w.closest('.content-card,.content-column,.panel');if(card)card.classList.toggle('action-menu-host-open',open)};w.querySelectorAll('.action-menu-item').forEach(item=>item.onclick=e=>{e.stopPropagation();w.classList.remove('is-open');trigger.setAttribute('aria-expanded','false');const card=w.closest('.content-card,.content-column,.panel');if(card)card.classList.remove('action-menu-host-open')})});if(!window.__actionMenusBound){window.__actionMenusBound=true;document.addEventListener('click',()=>$$('[data-action-menu].is-open').forEach(w=>{w.classList.remove('is-open');w.querySelector('[data-action-menu-trigger]')?.setAttribute('aria-expanded','false');const card=w.closest('.content-card,.content-column,.panel');if(card)card.classList.remove('action-menu-host-open')}))}}
function updateNotificationBadge(){const count=Number(state.notificationUnread||0);const el=$('#notificationCount');if(el)el.textContent=count;el?.classList.toggle('has-unread',count>0)}
function openNotifications(){const items=state.notifications||[];const list=$('#notificationsList');if(!list)return;list.innerHTML=items.map(n=>{const unread=!n.read_at;const type=String(n.type||n.notification_type||'INFO').toUpperCase();const icon=type.includes('APPROV')?'✓':type.includes('TASK')?'✓':type.includes('LEAD')?'◆':type.includes('ERROR')?'!':'•';return `<article class="notification-item-premium ${unread?'unread':'read'}" data-notification-id="${n.id}"><div class="notification-icon ${unread?'accent':''}">${icon}</div><div class="notification-content"><div class="notification-topline"><span class="notification-type">${esc(ptNotificationType(type))}</span>${unread?'<span class="notification-unread">NOVA</span>':''}<time>${n.created_at?new Date(n.created_at).toLocaleString('pt-BR'):''}</time></div><strong>${esc(n.title||'Notificação')}</strong><p>${esc(n.message||n.body||'')}</p><button type="button" class="notification-read-action" data-mark-notification="${n.id}">${unread?'Marcar como lida':'Lida'}</button></div></article>`}).join('')||'<div class="notification-empty-premium"><strong>Nenhuma notificação</strong><span>Você está em dia. Novos avisos aparecerão aqui.</span></div>';
$$('[data-mark-notification]').forEach(b=>b.onclick=async e=>{e.stopPropagation();try{await api(`/api/notifications/${b.dataset.markNotification}/read`,{method:'PATCH',body:JSON.stringify({})});await load();openNotifications()}catch(err){toast(err.message)}});$('#markNotificationsRead')?.addEventListener('click',async()=>{try{await api('/api/notifications/read-all',{method:'POST',body:JSON.stringify({})});await load();openNotifications()}catch(e){toast(e.message)}});$('#closeNotifications')?.addEventListener('click',()=>$('#notificationsModal')?.close());$('#notificationsModal')?.showModal()}
function ptNotificationType(type){const m={APPROVAL:'Aprovação',APPROVAL_PENDING:'Aprovação pendente',TASK:'Tarefa',TASK_ASSIGNED:'Tarefa atribuída',TASK_OVERDUE:'Tarefa atrasada',LEAD:'Lead',ERROR:'Erro',INFO:'Informação',SYSTEM:'Sistema'};return m[type]||'Notificação'}
function renderAnalytics(){const a=state.analytics?.overview||{};const campaigns=state.analytics?.campaigns||[];const channels=state.analytics?.channels||[];const content=state.analytics?.content||[];const maxBudget=Math.max(1,...campaigns.map(c=>Number(c.budget_cents)||0));$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Inteligência executiva · v0.8.2</span><h2>Dados para decidir onde crescer.</h2><p>KPIs operacionais, campanhas, conteúdo e execução em uma visão executiva.</p></div><button class="btn btn-secondary" id="refreshAnalytics">↻ Atualizar analytics</button></div><div class="kpis analytics-kpis"><div class="kpi"><small>Campanhas</small><strong>${a.campaigns||0}</strong><div class="trend">${a.active_campaigns||0} ativas</div></div><div class="kpi"><small>Orçamento</small><strong>R$ ${((Number(a.budget_cents)||0)/100).toLocaleString('pt-BR',{minimumFractionDigits:0})}</strong><div class="trend">planejado</div></div><div class="kpi"><small>Tarefas</small><strong>${a.tasks||0}</strong><div class="trend">${a.completed_tasks||0} concluídas</div></div><div class="kpi"><small>Execução</small><strong>${a.completion_rate||0}%</strong><div class="trend">tarefas</div></div><div class="kpi"><small>Conteúdo</small><strong>${a.content_items||0}</strong><div class="trend">${a.published_content||0} publicados</div></div><div class="kpi"><small>Publicação</small><strong>${a.content_publish_rate||0}%</strong><div class="trend">taxa</div></div></div><div class="analytics-grid"><section class="panel"><div class="panel-head"><h3>Performance por campanha</h3><span class="badge orange">GROWTH</span></div><div class="panel-body"><div class="analytics-table">${campaigns.map(c=>{const pct=Math.max(0,Math.min(100,Math.round((Number(c.budget_cents)||0)/maxBudget*100)));const exec=Number(c.task_count)?Math.round(Number(c.completed_tasks)/Number(c.task_count)*100):0;return `<div class="analytics-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.target_segment||'Growth B2B')} · ${badge(c.status)}</small></div><div class="analytics-metric"><span>Execução</span><b>${exec}%</b><div class="analytics-bar"><i class="progress-${exec}"></i></div></div><div class="analytics-metric"><span>Orçamento</span><b>R$ ${((Number(c.budget_cents)||0)/100).toLocaleString('pt-BR',{minimumFractionDigits:0})}</b><div class="analytics-bar"><i class="progress-${pct}"></i></div></div><div class="analytics-mini"><span>${c.content_count||0} conteúdos</span><span>${c.published_content||0} publicados</span></div></div>`}).join('')||'<div class="empty">Nenhuma campanha disponível.</div>'}</div></div></section><section class="panel"><div class="panel-head"><h3>Conteúdo por status</h3><span class="badge blue">PLANEJADOR</span></div><div class="panel-body"><div class="status-bars">${content.map(x=>`<div class="status-bar-row"><span>${esc(x.status.replace('_',' '))}</span><b>${x.count}</b><div><i class="progress-${Math.min(100,Number(x.count)*10)}"></i></div></div>`).join('')||'<div class="empty">Nenhum conteúdo.</div>'}</div></div></section></div><section class="panel analytics-channels"><div class="panel-head"><h3>Canais</h3><span class="badge">MARKETING</span></div><div class="panel-body"><div class="channel-grid">${channels.map(x=>`<article class="channel-card"><div><strong>${esc(x.channel.replace('_',' '))}</strong><small>${x.campaigns||0} campanhas</small></div><b>R$ ${((Number(x.budget_cents)||0)/100).toLocaleString('pt-BR',{minimumFractionDigits:0})}</b><span>${x.published_content||0}/${x.content_count||0} publicados</span></article>`).join('')||'<div class="empty">Nenhum canal com dados.</div>'}</div></div></section>`;if($('#refreshAnalytics'))$('#refreshAnalytics').onclick=()=>withPageLoader(()=>load(),'Atualizando analytics...')}
function renderCalendar(){const html=state.calendar.mode==='month'?renderCalendarMonth(state.calendar.date):state.calendar.mode==='week'?renderCalendarWeek(state.calendar.date):state.calendar.mode==='day'?renderCalendarDay(state.calendar.date):renderCalendarAgenda();const items=allCalendarItems();$('#content').innerHTML=`<div class="hero"><div><span class="section-label">Growth planning · v0.7.0</span><h2>Calendário profissional.</h2><p>Deadlines, reuniões, demonstrações e follow-ups em uma visão temporal única, com reagendamento e filtros.</p></div><div class="hero-actions"><button class="btn btn-secondary" id="calToday2">Hoje</button><button class="btn btn-primary" id="newCalendarEvent">+ Novo evento</button></div></div><section class="panel calendar-panel"><div class="panel-body"><div class="calendar-toolbar"><div><button class="icon-btn" id="calPrev" aria-label="Anterior">‹</button><button class="icon-btn" id="calToday">Hoje</button><button class="icon-btn" id="calNext" aria-label="Próximo">›</button></div><div class="calendar-heading"><span>PLANEJAMENTO OPERACIONAL</span><h2>${esc(calendarTitle())}</h2></div><div class="segmented"><button class="${state.calendar.mode==='month'?'active':''}" data-cal-mode="month">Mês</button><button class="${state.calendar.mode==='week'?'active':''}" data-cal-mode="week">Semana</button><button class="${state.calendar.mode==='day'?'active':''}" data-cal-mode="day">Dia</button><button class="${state.calendar.mode==='agenda'?'active':''}" data-cal-mode="agenda">Agenda</button></div></div>${calendarControls()}<div class="calendar-legend"><span><i class="legend-task"></i>Tarefa</span><span><i class="legend-meeting"></i>Reunião</span><span><i class="legend-demo"></i>Demonstração</span><span><i class="legend-follow"></i>Follow-up</span><span><i class="legend-deadline"></i>Deadline</span></div><div class="calendar-health"><span><b>${items.length}</b> itens</span><span><b>${state.events.filter(e=>e.is_overdue).length}</b> atrasadas</span><span><b>${state.events.filter(e=>e.is_critical).length}</b> críticas</span><span><b>${state.calendarEvents?.filter(e=>e.status==='SCHEDULED').length||0}</b> eventos</span></div>${html}</div></section>`;bindCalendar()}
function renderCalendarMonth(d){const y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1),start=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),cells=[];for(let i=0;i<start;i++)cells.push('<div class="cal-day muted-day"></div>');for(let day=1;day<=days;day++){const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,ev=itemsForDate(iso),today=new Date(),todayIso=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;cells.push(`<div class="cal-day ${iso===todayIso?'today':''}" data-drop-date="${iso}" data-new-date="${iso}"><div class="cal-num"><span>${day}</span><button class="day-add" type="button" data-new-event-date="${iso}" aria-label="Adicionar evento">+</button></div>${ev.map(calendarEvent).join('')||'<div class="cal-empty">Livre</div>'}</div>`)}return `<div class="calendar-grid"><div class="cal-week-head">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar-grid-body">${cells.join('')}</div></div>`}
function renderCalendarWeek(d){const day=new Date(d),monday=new Date(day),offset=(monday.getDay()+6)%7;monday.setDate(monday.getDate()-offset);const cells=[];for(let i=0;i<7;i++){const x=new Date(monday);x.setDate(monday.getDate()+i);const iso=`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`,ev=itemsForDate(iso);cells.push(`<div class="week-day intelligent-day ${iso===new Date().toISOString().slice(0,10)?'today':''}" data-drop-date="${iso}"><div class="week-day-head"><strong>${x.toLocaleDateString('pt-BR',{weekday:'short'})}</strong><span>${x.getDate()}</span></div><button class="day-quick-add" data-new-event-date="${iso}" type="button">+ evento</button>${ev.map(calendarEvent).join('')||'<div class="week-empty">Agenda livre</div>'}</div>`)}return `<div class="week-grid intelligent-week">${cells.join('')}</div>`}
function renderCalendarDay(d){const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,ev=itemsForDate(iso);return `<div class="day-agenda" data-drop-date="${iso}"><div class="day-focus"><div><span>VISÃO DIÁRIA</span><strong>${d.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'})}</strong></div><button class="btn btn-primary btn-sm" data-new-event-date="${iso}">+ evento</button></div>${ev.map(e=>`<div class="agenda-row">${calendarEvent(e)}<button class="btn btn-secondary btn-sm" data-calendar-open="${e.event_type?`event:${e.id}`:e.id}">Abrir</button></div>`).join('')||'<div class="empty">Nenhum compromisso previsto para este dia.</div>'}</div>`}
function renderCalendarAgenda(){const groups={};for(const e of allCalendarItems()){const k=String(e.due_date||e.start_at).slice(0,10);(groups[k]??=[]).push(e)}const keys=Object.keys(groups).sort();return `<div class="agenda-list">${keys.map(k=>`<section class="agenda-group"><header><strong>${formatDate(k)}</strong><span>${groups[k].length} itens</span></header>${groups[k].map(e=>`<div class="agenda-row">${calendarEvent(e)}<button class="btn btn-secondary btn-sm" data-calendar-open="${e.event_type?`event:${e.id}`:e.id}">Abrir</button></div>`).join('')}</section>`).join('')||'<div class="empty">Nenhum item encontrado no intervalo.</div>'}</div>`}
function bindCalendar(){const shift=async dir=>{const d=state.calendar.date;if(state.calendar.mode==='month')state.calendar.date=new Date(d.getFullYear(),d.getMonth()+dir,1);else state.calendar.date=new Date(d.getTime()+dir*(state.calendar.mode==='week'?7:1)*86400000);await loadCalendar();render()};$('#calPrev').onclick=()=>shift(-1);$('#calNext').onclick=()=>shift(1);$('#calToday').onclick=async()=>{state.calendar.date=new Date();await loadCalendar();render()};$('#calToday2').onclick=async()=>{state.calendar.date=new Date();await loadCalendar();render()};$('#newCalendarEvent').onclick=()=>newCalendarEvent();$$('[data-cal-mode]').forEach(b=>b.onclick=async()=>{state.calendar.mode=b.dataset.calMode;await loadCalendar();render()});const apply=async()=>{state.calendar.search=$('#calSearch').value.trim();state.calendar.phase_id=$('#calPhase').value;state.calendar.assignee=$('#calAssignee').value;state.calendar.event_type=$('#calType').value;state.calendar.priority=$('#calPriority').value;state.calendar.overdue=$('#calOverdue').checked;await loadCalendar();render()};$('#calSearch').onkeydown=e=>{if(e.key==='Enter')apply()};['calPhase','calAssignee','calType','calPriority','calOverdue'].forEach(id=>$('#'+id).onchange=apply);$$('[data-new-event-date]').forEach(b=>b.onclick=e=>{e.stopPropagation();const [y,m,day]=b.dataset.newEventDate.split('-').map(Number);newCalendarEvent(new Date(y,m-1,day))});$$('[data-calendar-open]').forEach(b=>b.onclick=()=>{const v=b.dataset.calendarOpen;if(v.startsWith('event:'))return calendarEventDetails(v.slice(6));taskDetails(v)});$$('[data-calendar-kind="task"]').forEach(b=>{b.onclick=()=>taskDetails(b.dataset.calendarId);b.ondragstart=e=>{e.dataTransfer.setData('application/json',JSON.stringify({kind:'task',id:b.dataset.calendarId}));b.classList.add('dragging')};b.ondragend=()=>b.classList.remove('dragging')});$$('[data-calendar-kind="event"]').forEach(b=>{b.onclick=()=>calendarEventDetails(b.dataset.calendarId);b.ondragstart=e=>{e.dataTransfer.setData('application/json',JSON.stringify({kind:'event',id:b.dataset.calendarId}));b.classList.add('dragging')};b.ondragend=()=>b.classList.remove('dragging')});$$('[data-drop-date]').forEach(cell=>{cell.ondragover=e=>{e.preventDefault();cell.classList.add('drop-target')};cell.ondragleave=()=>cell.classList.remove('drop-target');cell.ondrop=async e=>{e.preventDefault();cell.classList.remove('drop-target');let payload;try{payload=JSON.parse(e.dataTransfer.getData('application/json'))}catch{return}const due_date=cell.dataset.dropDate;if(!payload?.id||!due_date)return;try{if(payload.kind==='task')await api(`/api/calendar/${payload.id}/reschedule`,{method:'PATCH',body:JSON.stringify({due_date})});else await api(`/api/calendar-events/${payload.id}`,{method:'PATCH',body:JSON.stringify({start_at:`${due_date}T09:00:00.000Z`})});toast('Item reagendado.');await loadCalendar();render()}catch(err){toast(err.message)}}})}
function calendarEventDetails(id){const e=(state.calendarEvents||[]).find(x=>x.id===id);if(!e)return;openModal('Detalhes do evento',`<div class="detail-hero"><div><span class="eyebrow">${esc(e.event_type)}</span><h3>${esc(e.title)}</h3><p>${esc(e.description||'Sem descrição.')}</p></div><span class="badge ${e.status==='CANCELLED'?'red':e.status==='COMPLETED'?'green':'orange'}">${esc(e.status)}</span></div><div class="detail-grid"><div class="detail-stat"><small>Início</small><strong>${new Date(e.start_at).toLocaleString('pt-BR')}</strong></div><div class="detail-stat"><small>Término</small><strong>${e.end_at?new Date(e.end_at).toLocaleString('pt-BR'):'—'}</strong></div><div class="detail-stat"><small>Responsável</small><strong>${esc(e.owner_name||'—')}</strong></div><div class="detail-stat"><small>Local</small><strong>${esc(e.location||'—')}</strong></div></div><div class="form-actions"><button class="btn btn-secondary" id="closeEvent">Fechar</button></div>`);$('#closeEvent').onclick=closeModal}
function bindPhaseCards(){$$('[data-open-phase]').forEach(b=>b.onclick=e=>{e.stopPropagation();phaseDetails(b.dataset.openPhase)});$$('[data-phase-details]').forEach(b=>{b.onclick=()=>phaseDetails(b.dataset.phaseDetails);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();phaseDetails(b.dataset.phaseDetails)}}})}
function bindViewActions(){$$('[data-view-action]').forEach(b=>b.onclick=()=>{state.view=b.dataset.viewAction;render()});$$('[data-task]').forEach(b=>b.onclick=()=>taskDetails(b.dataset.task));bindPhaseCards()}
async function boot(){const me=await api('/api/auth/me');if(!me.data.user){$('#login').classList.remove('hidden');hidePageLoader();return}state.user=me.data.user;$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#userName').textContent=state.user.name;$('#userRole').textContent=ptLabel('role',state.user.role);$('#avatar').textContent=state.user.name[0].toUpperCase();showPageLoader('Carregando workspace...');try{await load()}finally{hidePageLoader()}}
// Robust delegated opener: keeps Tarefas > Abrir functional after every render/re-render.
document.addEventListener('click',e=>{if(e.target.closest('[data-edit-task],[data-delete-task],[data-edit-subtask],[data-delete-subtask]'))return;const opener=e.target.closest('[data-open-task],[data-task]');if(!opener)return;if(e.target.closest('button[data-open-task]')||opener.matches('[data-task]')){const id=opener.dataset.openTask||opener.dataset.task;if(id){e.preventDefault();e.stopPropagation();taskDetails(id)}}},{capture:true});
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{showPageLoader('Autenticando e preparando seu workspace...');const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});state.user=r.data.user;await boot()}catch(err){hidePageLoader();toast(err.message)}};
$('#notificationsBtn').onclick=openNotifications;updateNotificationBadge();$('#logout').onclick=async()=>{showPageLoader('Encerrando sessão...');try{await api('/api/auth/logout',{method:'POST'});location.reload()}catch(e){hidePageLoader();toast(e.message)}};$('#refresh').onclick=()=>withPageLoader(()=>load(),'Atualizando workspace...').then(()=>toast('Dados atualizados.')).catch(e=>toast(e.message));$('#newTask').onclick=()=>newTask();$('#closeModal').onclick=closeModal;$('#openSidebar').onclick=()=>$('#sidebar').classList.add('open');$('#closeSidebar').onclick=()=>$('#sidebar').classList.remove('open');$$('.nav-item').forEach(b=>b.onclick=async()=>{const nextView=b.dataset.view;$('#sidebar').classList.remove('open');await withPageLoader(async()=>{state.view=nextView;if(state.view==='calendar')await loadCalendar();await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));render()},`Abrindo ${b.textContent.replace(/\d+/g,'').trim()}...`)});boot().catch(e=>{hidePageLoader();toast(e.message)});
